export class SpacingGridComponent {
  private readonly _document = inject(DOCUMENT);

  readonly kind = input.required<SpacingKind>();

  protected readonly BOXES = [0, 1, 2, 3, 4, 5];
  protected readonly sections = signal<SpacingSection[]>([]);
  protected readonly copied = signal<string | null>(null);

  protected config(): KindConfig {
    return CONFIG[this.kind()];
  }

  constructor() {
    afterNextRender(() => this._load());
  }

  protected copy(className: string): void {
    void navigator.clipboard?.writeText(className);
    this.copied.set(className);

    setTimeout(() => this.copied.update((current) => (current === className ? null : current)), 1200);
  }

  private _load(): void {
    const config = this.config();
    const byVariant = new Map<string, SpacingItem[]>();
    const seen = new Set<string>();

    for (const sheet of Array.from(this._document.styleSheets)) {
      let rules: CSSRuleList;

      try {
        rules = sheet.cssRules;
      } catch {
        continue;
      }

      for (const rule of Array.from(rules)) {
        if (!(rule instanceof CSSStyleRule)) {
          continue;
        }

        const match = config.test.exec(rule.selectorText);

        if (!match || seen.has(rule.selectorText)) {
          continue;
        }

        seen.add(rule.selectorText);

        const variant = config.variantOf(match);
        const scale = config.scaleOf(match);
        const property = rule.style.item(0);
        const value = property ? rule.style.getPropertyValue(property).trim() : '';
        const items = byVariant.get(variant) ?? [];

        items.push({ className: rule.selectorText.slice(1), scale, label: this._formatLabel(value) });
        byVariant.set(variant, items);
      }
    }

    const sections: SpacingSection[] = [];

    for (const { key, title } of config.sections) {
      const items = byVariant.get(key);

      if (items?.length) {
        items.sort((a, b) => a.scale - b.scale);
        sections.push({ key, title, items });
      }
    }

    this.sections.set(sections);
  }

  private _formatLabel(value: string): string {
    if (!value) {
      return '';
    }

    const px = value.endsWith('rem')
      ? parseFloat(value) * 16
      : value.endsWith('px')
        ? parseFloat(value)
        : Number.NaN;

    return Number.isNaN(px) ? value : `${px}px · ${value}`;
  }
}

export interface MudCivilDate {
  y: number;
  m: number;
  d: number;
}

const ISO_PATTERN = /^(\d{4})-(\d{2})-(\d{2})$/;

/**
 * Days between the civil date and 1970-01-01, by Howard Hinnant's
 * `days_from_civil`. Pure integer arithmetic — no `Date`, so no timezone or
 * DST transition can influence the result.
 */
function daysFromCivil({ y, m, d }: MudCivilDate): number {
  const year = y - (m <= 2 ? 1 : 0);
  const era = Math.floor(year / 400);
  const yoe = year - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;

  return era * 146097 + doe - 719468;
}

/** Inverse of {@link daysFromCivil}. */
function civilFromDays(days: number): MudCivilDate {
  const z = days + 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor(
    (doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365,
  );
  const year = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);

  return { y: year + (m <= 2 ? 1 : 0), m, d };
}

export function isLeapYear(year: number): boolean {
  return (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
}

/** `month` is 1-indexed. */
export function daysInMonth(year: number, month: number): number {
  if (month === 2) return isLeapYear(year) ? 29 : 28;

  return [4, 6, 9, 11].includes(month) ? 30 : 31;
}

/**
 * True only for a `YYYY-MM-DD` string naming a date that exists. Datetime
 * strings are rejected on purpose — see the strict-format decision in the spec.
 */
export function isValidIso(value: string): boolean {
  const match = ISO_PATTERN.exec(value);

  if (!match) return false;

  const y = Number(match[1]);
  const m = Number(match[2]);
  const d = Number(match[3]);

  return m >= 1 && m <= 12 && d >= 1 && d <= daysInMonth(y, m);
}

export function parseIso(value: string): MudCivilDate | null {
  if (!isValidIso(value)) return null;

  return { y: Number(value.slice(0, 4)), m: Number(value.slice(5, 7)), d: Number(value.slice(8, 10)) };
}

export function toIso({ y, m, d }: MudCivilDate): string {
  return `${String(y).padStart(4, '0')}-${String(m).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
}

/** Years outside this range cannot round-trip through a four-digit ISO string. */
function isRepresentable({ y }: MudCivilDate): boolean {
  return y >= 0 && y <= 9999;
}

/** 0 = Sunday … 6 = Saturday. 1970-01-01 was a Thursday, hence the +4. */
export function dayOfWeek(iso: string): number {
  const date = parseIso(iso);

  if (!date) return 0;

  return (((daysFromCivil(date) + 4) % 7) + 7) % 7;
}

export function addDays(iso: string, amount: number): string {
  const date = parseIso(iso);

  if (!date) return iso;

  const next = civilFromDays(daysFromCivil(date) + amount);

  return isRepresentable(next) ? toIso(next) : iso;
}

/** Clamps the day to the target month's length: Jan 31 + 1 month = Feb 28/29. */
export function addMonths(iso: string, amount: number): string {
  const date = parseIso(iso);

  if (!date) return iso;

  const total = date.y * 12 + (date.m - 1) + amount;
  const y = Math.floor(total / 12);
  const m = (((total % 12) + 12) % 12) + 1;
  const next = { y, m, d: Math.min(date.d, daysInMonth(y, m)) };

  return isRepresentable(next) ? toIso(next) : iso;
}

/** First day of the containing month; unusable input passes through. */
export function startOfMonth(iso: string): string {
  const date = parseIso(iso);

  return date ? toIso({ ...date, d: 1 }) : iso;
}

/** ISO dates sort lexicographically, so this is a plain string comparison. */
export function compareIso(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/**
 * Orders a range's endpoints, so entering the later date first still yields a
 * valid range. Shared by the calendar's range-completion path and the field's
 * range commit — the two used to make opposite choices for the same user
 * intent (the calendar swapped, the field nullified the end), which is exactly
 * what a shared helper prevents from drifting apart again.
 */
export function normalizeRange(a: string, b: string): { start: string; end: string } {
  return compareIso(a, b) <= 0 ? { start: a, end: b } : { start: b, end: a };
}

/** Inclusive on both bounds; an absent bound is unbounded. */
export function isWithin(iso: string, min?: string, max?: string): boolean {
  if (min && compareIso(iso, min) < 0) return false;

  if (max && compareIso(iso, max) > 0) return false;

  return true;
}

/** Passes an ISO date through, and anything else out. Bounds arriving from a
 *  signal-forms schema are name-matched at runtime and are not type-checked. */
export function toValidIsoOrUndefined(value: unknown): string | undefined {
  return typeof value === 'string' && isValidIso(value) ? value : undefined;
}

// ----- public converters (exported from the entry point) -----

/** Reads the LOCAL calendar date off a `Date`. */
export function mudDateFromDate(date: Date): string {
  return toIso({ y: date.getFullYear(), m: date.getMonth() + 1, d: date.getDate() });
}

/**
 * Local **noon**, not midnight: a DST transition can move midnight across a
 * day boundary, noon cannot. `new Date('2026-08-27')` would parse as UTC and
 * reintroduce exactly the bug this library avoids.
 */
export function mudDateToDate(iso: string): Date {
  const date = parseIso(iso);

  if (!date) return new Date(NaN);

  return new Date(date.y, date.m - 1, date.d, 12, 0, 0, 0);
}

export function mudToday(): string {
  return mudDateFromDate(new Date());
}

export function mudAddDays(iso: string, amount: number): string {
  return addDays(iso, amount);
}

import { isValidIso, toIso } from './date-core';

export type MudDateFormat = 'DD/MM/YYYY' | 'MM/DD/YYYY' | 'YYYY-MM-DD';
export type MudDateSegmentKind = 'DD' | 'MM' | 'YYYY';

export interface MudDateSegment {
  kind: MudDateSegmentKind;
  /** Digit count: 2 for DD/MM, 4 for YYYY. */
  length: number;
  /** Offset of the segment's first digit within the display string. */
  start: number;
}

export interface MudDateFormatSpec {
  format: MudDateFormat;
  separator: string;
  segments: MudDateSegment[];
  /** Length of a fully-typed display value. */
  length: number;
}

const ORDERS: Record<MudDateFormat, { separator: string; kinds: MudDateSegmentKind[] }> = {
  'DD/MM/YYYY': { separator: '/', kinds: ['DD', 'MM', 'YYYY'] },
  'MM/DD/YYYY': { separator: '/', kinds: ['MM', 'DD', 'YYYY'] },
  'YYYY-MM-DD': { separator: '-', kinds: ['YYYY', 'MM', 'DD'] },
};

const specCache = new Map<MudDateFormat, MudDateFormatSpec>();

export function formatSpec(format: MudDateFormat): MudDateFormatSpec {
  const cached = specCache.get(format);

  if (cached) return cached;

  const { separator, kinds } = ORDERS[format];
  let start = 0;

  const segments = kinds.map((kind) => {
    const length = kind === 'YYYY' ? 4 : 2;
    const segment: MudDateSegment = { kind, length, start };

    start += length + 1;

    return segment;
  });

  const spec: MudDateFormatSpec = { format, separator, segments, length: format.length };

  specCache.set(format, spec);

  return spec;
}

function digitsOf(value: string): string {
  return value.replace(/\D/g, '');
}

/**
 * Strips everything that isn't a digit, then walks the segment spec inserting
 * the separator between segments. Typing `1504` yields `15/04`, so the
 * separator is never something the user has to press.
 *
 * The separator is LAZY — emitted only when a following digit exists — exactly
 * as `phone-input`'s `phone-mask` does it. Appending it the instant a segment
 * filled (`15` → `15/`) made the field un-deletable: Backspace removes the
 * `/`, the re-mask puts it straight back, and the user can never delete the
 * month, never the day, and never clear the field with Backspace at all.
 */
export function formatMasked(raw: string, spec: MudDateFormatSpec): string {
  const maxDigits = spec.segments.reduce((sum, segment) => sum + segment.length, 0);
  const digits = digitsOf(raw).slice(0, maxDigits);

  if (!digits) return '';

  let out = '';
  let next = 0;

  for (const segment of spec.segments) {
    const chunk = digits.slice(next, next + segment.length);

    if (!chunk) break;

    out += chunk;
    next += chunk.length;

    // Nothing typed past this segment yet, so there is no separator to write —
    // and the last segment can never have anything past it.
    if (next >= digits.length) break;

    out += spec.separator;
  }

  return out;
}

/** The untyped tail of the format pattern, rendered behind the caret. */
export function ghostRemainder(display: string, spec: MudDateFormatSpec): string {
  return spec.format.slice(display.length);
}

/** ISO string for a complete, real date; `null` while incomplete or impossible. */
export function displayToIso(display: string, spec: MudDateFormatSpec): string | null {
  if (display.length !== spec.length) return null;

  const part = (kind: MudDateSegmentKind): number => {
    const segment = spec.segments.find((candidate) => candidate.kind === kind)!;

    return Number(display.slice(segment.start, segment.start + segment.length));
  };

  const iso = toIso({ y: part('YYYY'), m: part('MM'), d: part('DD') });

  return isValidIso(iso) ? iso : null;
}

export function isoToDisplay(iso: string, spec: MudDateFormatSpec): string {
  if (!isValidIso(iso)) return '';

  const values: Record<MudDateSegmentKind, string> = {
    YYYY: iso.slice(0, 4),
    MM: iso.slice(5, 7),
    DD: iso.slice(8, 10),
  };

  return spec.segments.map((segment) => values[segment.kind]).join(spec.separator);
}

export function digitsBefore(value: string, caret: number): number {
  return digitsOf(value.slice(0, Math.max(0, caret))).length;
}

/**
 * Offset immediately after the nth digit, so a re-mask restores the caret to
 * the digit the user was working on instead of flinging it to the end.
 *
 * Task 14 needed an extra clause here — when the nth digit was the LAST one
 * typed and a just-auto-inserted separator followed it, the caret had to land
 * after that separator, or it would visibly stall one position short of where
 * forward typing continues. `formatMasked`'s separator is now lazy, so a
 * masked string always ENDS on a digit: for the last digit, `i + 1` is already
 * the end of the string and there is no separator left to step over. The
 * clause was removed with the bug that made it necessary.
 */
export function caretForDigitIndex(masked: string, digitIndex: number): number {
  if (digitIndex <= 0) return 0;

  let seen = 0;

  for (let i = 0; i < masked.length; i += 1) {
    if (!/\d/.test(masked[i])) continue;

    seen += 1;

    if (seen === digitIndex) return i + 1;
  }

  return masked.length;
}

