import { computed, Directive, effect, ElementRef, inject, input, PLATFORM_ID, Renderer2 } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export type MudBadgeSize = 'extra-small' | 'small' | 'medium' | 'large' | 'extra-large';
/**
 * `default`, `brand`, `positive`, `warning`, `danger` mirror the official
 * design-system palette; `dark`, `light`, `neutral`, `accent` are extra
 * (`dark` renders like `default`, `accent` uses the warning-accent surface).
 */
export type MudBadgeColor =
  | 'default'
  | 'brand'
  | 'positive'
  | 'warning'
  | 'danger'
  | 'dark'
  | 'light'
  | 'neutral'
  | 'accent';
export type MudBadgePosition =
  | 'above after'
  | 'above before'
  | 'below before'
  | 'below after'
  | 'before'
  | 'after'
  | 'above'
  | 'below';
export type MudBadgeVariant = 'count' | 'dot';

const SIZE_CLASSES: Record<MudBadgeSize, string> = {
  'extra-small': 'badge--xs',
  small: 'badge--sm',
  medium: 'badge--md',
  large: 'badge--lg',
  'extra-large': 'badge--xl',
};

let nextId = 0;

declare const ngDevMode: boolean | undefined;

/**
 * ```html
 * <button mudButton mudBadge="5" badgeColor="danger">Inbox</button>
 * ```
 */
@Directive({
  selector: '[mudBadge]',
  exportAs: 'mudBadge',
  host: { class: 'mud-badge-host' },
})
export class MudBadge {
  private readonly _renderer = inject(Renderer2);
  private readonly _host = inject(ElementRef<HTMLElement>).nativeElement;
  private readonly _descriptionId = `mud-badge-description-${nextId++}`;

  readonly mudBadge = input<string | number | null>(null);
  readonly badgeSize = input<MudBadgeSize>('medium');
  readonly badgeColor = input<MudBadgeColor>('neutral');
  readonly badgePosition = input<MudBadgePosition>('above after');
  readonly badgeMax = input<number | null, number | string | null | undefined>(null, {
    transform: (value) => {
      if (value == null || value === '') return null;

      const parsed = Number(value);

      if (Number.isNaN(parsed)) {
        if (typeof ngDevMode === 'undefined' || ngDevMode) {
          console.warn(`mudBadge: badgeMax "${value}" is not a number; the badge count will not be truncated.`);
        }

        return null;
      }

      return parsed;
    },
  });
  readonly badgeVariant = input<MudBadgeVariant>('count');
  readonly badgeDescription = input<string | null>(null);

  private _badge: HTMLElement | null = null;
  private _description: HTMLElement | null = null;

  private readonly _effectiveVariant = computed<MudBadgeVariant>(() => {
    if (this.badgeVariant() === 'count' && this.badgeSize() === 'extra-small') {
      if (typeof ngDevMode === 'undefined' || ngDevMode) {
        console.warn(
          'mudBadge: size "extra-small" is dot-only; rendering a dot instead of the count. ' +
            'Use badgeDescription to announce the count, or size "small" and up to display it.',
        );
      }

      return 'dot';
    }

    return this.badgeVariant();
  });

  private readonly _content = computed<string | null>(() => {
    if (this._effectiveVariant() === 'dot') return '';

    const value = this.mudBadge();

    if (value == null || value === '') return null;

    const max = this.badgeMax();
    const count = typeof value === 'number' ? value : Number(value);

    if (max != null && Number.isFinite(count) && count > max) return `${max}+`;

    return `${value}`;
  });

  private readonly _badgeClasses = computed(() => {
    const position = this.badgePosition();
    const classes = [
      'badge',
      SIZE_CLASSES[this.badgeSize()],
      `badge--solid-${this.badgeColor()}`,
      'badge--fixed',
      position.includes('below') ? 'badge--below' : 'badge--above',
      position.includes('before') ? 'badge--before' : 'badge--after',
    ];

    if (this._effectiveVariant() === 'dot') classes.push('badge--dot');

    return classes.join(' ');
  });

  constructor() {
    /**
     * @description The badge span is created imperatively, so a server-rendered copy
     * could never be claimed during hydration - it would end up duplicated
     * next to the client-created one. Browser-only keeps SSR markup clean.
     * */
    if (!isPlatformBrowser(inject(PLATFORM_ID))) return;

    effect(() => {
      const content = this._content();

      if (content === null) {
        this._detachBadge();
        this._detachDescription();

        return;
      }

      const badge = this._badge ?? this._attachBadge();

      this._renderer.setAttribute(badge, 'class', this._badgeClasses());
      this._renderer.setProperty(badge, 'textContent', content);

      const description = this.badgeDescription();

      if (description) {
        const element = this._description ?? this._attachDescription();

        this._renderer.setProperty(element, 'textContent', description);
        this._renderer.setAttribute(badge, 'aria-hidden', 'true');
      } else {
        this._detachDescription();
        this._renderer.removeAttribute(badge, 'aria-hidden');
      }
    });
  }

  private _attachBadge(): HTMLElement {
    const badge = this._renderer.createElement('span') as HTMLElement;

    this._renderer.appendChild(this._host, badge);
    this._badge = badge;

    return badge;
  }

  private _detachBadge(): void {
    if (!this._badge) return;

    this._renderer.removeChild(this._host, this._badge);
    this._badge = null;
  }

  private _attachDescription(): HTMLElement {
    const element = this._renderer.createElement('span') as HTMLElement;

    this._renderer.setAttribute(element, 'id', this._descriptionId);
    this._renderer.setAttribute(element, 'class', 'mud-badge-description');
    // Polite live region so a changing description (e.g. an updated unread
    // count) is announced, matching the official badge's role="status".
    this._renderer.setAttribute(element, 'role', 'status');
    this._renderer.setAttribute(element, 'aria-live', 'polite');
    this._renderer.appendChild(this._host, element);
    this._description = element;

    const ids = this._describedByIds();

    if (!ids.includes(this._descriptionId)) ids.push(this._descriptionId);

    this._renderer.setAttribute(this._host, 'aria-describedby', ids.join(' '));

    return element;
  }

  private _detachDescription(): void {
    if (!this._description) return;

    this._renderer.removeChild(this._host, this._description);
    this._description = null;

    const ids = this._describedByIds().filter((id) => id !== this._descriptionId);

    if (ids.length) {
      this._renderer.setAttribute(this._host, 'aria-describedby', ids.join(' '));
    } else {
      this._renderer.removeAttribute(this._host, 'aria-describedby');
    }
  }

  private _describedByIds(): string[] {
    const value = this._host.getAttribute('aria-describedby');

    return value ? value.split(/\s+/).filter(Boolean) : [];
  }
}

import { booleanAttribute, computed, Directive, input } from '@angular/core';
import { MudButtonBase } from './mud-button-base';

declare const ngDevMode: boolean | undefined;

export type MudButtonVariant = 'filled' | 'outlined' | 'text';
export type MudButtonColor = 'primary' | 'secondary' | 'strict' | 'neutral' | 'destructive';
export type MudButtonSize = 'large' | 'medium' | 'small';
export type MudButtonShape = 'rectangular' | 'circular';

const VARIANT_CLASS_INFIX: Record<MudButtonVariant, string> = {
  filled: '',
  outlined: '-outline',
  text: '-text',
};

const SIZE_CLASSES: Record<MudButtonSize, string> = {
  large: '',
  medium: 'mud-btn-md',
  small: 'mud-btn-sm',
};

const SUPPORTED_COLORS: Record<MudButtonVariant, readonly MudButtonColor[]> = {
  filled: ['primary', 'secondary', 'strict', 'neutral', 'destructive'],
  outlined: ['primary', 'strict', 'destructive'],
  text: ['primary', 'strict', 'destructive'],
};

/**
 * ```html
 * <button mudButton>Save</button>
 * <button mudButton="outlined" color="destructive" size="small">Delete</button>
 * <a mudButton="text" color="strict" shape="circular" href="/back">Back</a>
 * ```
 */
@Directive({
  selector: 'button[mudButton], a[mudButton]',
  exportAs: 'mudButton',
})
export class MudButton extends MudButtonBase {
  readonly mudButton = input.required<MudButtonVariant, MudButtonVariant | ''>({
    transform: (value) => value || 'filled',
  });
  readonly color = input<MudButtonColor>('primary');
  readonly size = input<MudButtonSize>('large');
  readonly shape = input<MudButtonShape>('rectangular');
  /** @description Stretches the button to fill its container's width. */
  readonly fullWidth = input(false, { transform: booleanAttribute });

  private readonly _effectiveColor = computed(() => {
    const variant = this.mudButton();
    const color = this.color();

    if (!SUPPORTED_COLORS[variant].includes(color)) {
      if (typeof ngDevMode === 'undefined' || ngDevMode) {
        console.warn(
          `mudButton: color "${color}" is not supported by the "${variant}" variant; falling back to "primary". ` +
            `Supported colors: ${SUPPORTED_COLORS[variant].join(', ')}.`,
        );
      }

      return 'primary';
    }

    return color;
  });

  protected override readonly _hostClasses = computed(() => {
    const classes = ['mud-btn', `mud-btn${VARIANT_CLASS_INFIX[this.mudButton()]}-${this._effectiveColor()}`];
    const sizeClass = SIZE_CLASSES[this.size()];

    if (sizeClass) classes.push(sizeClass);

    if (this.shape() === 'circular') classes.push('mud-btn-rounded');

    if (this.fullWidth()) classes.push('mud-btn-full');

    if (this.loading()) classes.push('mud-btn-loading');

    return classes.join(' ');
  });
}

import { booleanAttribute, computed, Directive, ElementRef, inject, input } from '@angular/core';
import type { Signal } from '@angular/core';

/**
 * Shared behavior for mudButton/mudIconButton: disabled semantics for
 * buttons and anchors, and the loading state with its accessibility contract.
 */
@Directive({
  host: {
    '[class]': '_hostClasses()',
    '[attr.disabled]': '_nativeDisabled()',
    '[attr.aria-disabled]': '_ariaDisabled()',
    '[attr.aria-busy]': "loading() ? 'true' : null",
    '[attr.tabindex]': '_tabIndex()',
  },
})
export abstract class MudButtonBase {
  protected readonly _element = inject(ElementRef<HTMLElement>).nativeElement;
  protected readonly _isAnchor = this._element.tagName === 'A';

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly loading = input(false, { transform: booleanAttribute });

  protected abstract readonly _hostClasses: Signal<string>;

  // Anchors can't be natively disabled; loading must not drop focus mid-action.
  protected readonly _nativeDisabled = computed(() => (!this._isAnchor && this.disabled() ? '' : null));

  protected readonly _ariaDisabled = computed(() =>
    this.loading() || (this._isAnchor && this.disabled()) ? 'true' : null,
  );

  protected readonly _tabIndex = computed(() => (this._isAnchor && this.disabled() ? '-1' : null));

  constructor() {
    // Capture phase so the block runs before any consumer (click) listener.
    this._element.addEventListener(
      'click',
      (event: Event) => {
        if (this.disabled() || this.loading()) {
          event.preventDefault();
          event.stopImmediatePropagation();
        }
      },
      { capture: true },
    );
  }
}

import { Directive, DestroyRef, computed, inject, input } from '@angular/core';
import { MudDialogRef } from './mud-dialog-ref';

let nextDialogTitleId = 0;

/**
 * ```html
 * <h2 mudDialogTitle>Sigur ștergeți?</h2>
 * ```
 */
@Directive({
  selector: '[mudDialogTitle]',
  host: { class: 'dialog__title', '[id]': '_id' },
})
export class MudDialogTitle {
  /** @docs-private */
  protected readonly _id = `mud-dialog-title-${nextDialogTitleId++}`;
  private readonly _ref = inject(MudDialogRef, { optional: true });

  constructor() {
    this._ref?._container?._addAriaLabelledBy(this._id);

    inject(DestroyRef).onDestroy(() => this._ref?._container?._removeAriaLabelledBy(this._id));
  }
}

/** The scroll region between title and actions. */
@Directive({ selector: '[mudDialogContent]', host: { class: 'dialog__content' } })
export class MudDialogContent {}

/** Footer action row; stacks on mobile, or always via layout="stacked". */
@Directive({
  selector: '[mudDialogActions]',
  host: { '[class]': '_classes()' },
})
export class MudDialogActions {
  /** @description inline (default) or stacked full-width buttons, primary on top. */
  readonly layout = input<'inline' | 'stacked'>('inline');

  /** @docs-private */
  protected readonly _classes = computed(() =>
    this.layout() === 'stacked' ? 'dialog__actions dialog__actions--stacked' : 'dialog__actions',
  );
}

/**
 * ```html
 * <button mudButton [mudDialogClose]="true">Șterge</button>
 * ```
 */
@Directive({
  selector: '[mudDialogClose]',
  host: { '[attr.type]': 'type()', '(click)': '_close()' },
})
export class MudDialogClose<R = unknown> {
  /** @description Result emitted through MudDialogRef.closed. */
  readonly mudDialogClose = input<R | undefined>(undefined);

  /** @description Native button `type`; defaults to `'button'`. */
  readonly type = input('button');

  private readonly _ref = inject(MudDialogRef) as MudDialogRef<R>;

  /** @docs-private */
  protected _close(): void {
    this._ref.close(this.mudDialogClose(), 'action');
  }
}

