import { booleanAttribute, computed, Directive, ElementRef, inject, input, PLATFORM_ID } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';

export type MudLinkStyle = 'primary' | 'strict';
export type MudLinkSize = 'large' | 'medium' | 'small' | 'extra-small';
export type MudLinkUnderline = 'always' | 'hover' | 'none';
export type MudLinkTouchTarget = 'auto' | 'pointer' | 'touch' | 'none';

const SIZE_CLASSES: Record<MudLinkSize, string> = {
  large: 'link-lg',
  medium: 'link-md',
  small: 'link-sm',
  'extra-small': 'link-xs',
};

const UNDERLINE_CLASSES: Record<MudLinkUnderline, string> = {
  always: 'link-underline',
  hover: 'link-underline-hover',
  none: 'link-no-underline',
};

/**
 * ```html
 * <a mudLink href="/services">Services</a>
 * <a mudLink="strict" size="small" underline="none" href="/terms">Terms</a>
 * <a mudLink href="https://gov.md" target="_blank">Portal</a> <!-- auto external icon + rel -->
 * ```
 */
@Directive({
  selector: 'a[mudLink]',
  exportAs: 'mudLink',
  host: {
    '[class]': '_hostClasses()',
    '[attr.aria-disabled]': "disabled() ? 'true' : null",
    '[attr.tabindex]': "disabled() ? '-1' : null",
  },
})
export class MudLink {
  private readonly _element = inject(ElementRef<HTMLElement>).nativeElement;
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  readonly mudLink = input.required<MudLinkStyle, MudLinkStyle | ''>({
    transform: (value) => value || 'primary',
  });
  readonly size = input<MudLinkSize>('medium');
  readonly underline = input<MudLinkUnderline>('always');
  readonly touchTarget = input<MudLinkTouchTarget>('auto');
  readonly disabled = input(false, { transform: booleanAttribute });
  /**
   * @description When true (the default), anchors with `target="_blank"` and no trailing
   * icon get the external-link indicator glyph after the label.
   */
  readonly external = input(true, { transform: booleanAttribute });

  // SSR has no media queries; assume fine pointer until the browser hydrates.
  private readonly _coarsePointer =
    this._isBrowser && typeof matchMedia === 'function' && matchMedia('(pointer: coarse)').matches;

  private readonly _targetClass = computed(() => {
    const target = this.touchTarget();

    if (target === 'none') return null;

    if (target === 'auto') return this._coarsePointer ? 'link-target-touch' : 'link-target-pointer';

    return `link-target-${target}`;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['link', `link-${this.mudLink()}`, SIZE_CLASSES[this.size()]];

    classes.push(UNDERLINE_CLASSES[this.underline()]);

    if (this.external()) classes.push('link-external');

    const targetClass = this._targetClass();

    if (targetClass) classes.push(targetClass);

    return classes.join(' ');
  });

  constructor() {
    // New-tab anchors get the official safety rel unless the consumer set one.
    const anchor = this._element as HTMLAnchorElement;

    if (anchor.getAttribute?.('target') === '_blank' && !anchor.getAttribute('rel')) {
      anchor.setAttribute('rel', 'noopener noreferrer');
    }

    // Capture phase so the block runs before any consumer (click) listener.
    this._element.addEventListener(
      'click',
      (event: Event) => {
        if (this.disabled()) {
          event.preventDefault();
          event.stopImmediatePropagation();
        }
      },
      { capture: true },
    );
  }
}

import {
  afterNextRender,
  DestroyRef,
  Directive,
  ElementRef,
  inject,
  Injector,
  input,
  output,
  PLATFORM_ID,
  signal,
} from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Overlay } from '@angular/cdk/overlay';
import type { ConnectedPosition, OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import type { Subscription } from 'rxjs';

import type { MudMenu } from './mud-menu.component';
import { MudMenuItem } from './mud-menu-item.component';
import { MUD_MENU_PANEL } from './mud-menu.types';
import type { MudMenuPositionX, MudMenuPositionY, MudMenuTriggerHandle } from './mud-menu.types';

const SUBMENU_HOVER_DELAY_MS = 120;

function rootPositions(x: MudMenuPositionX, y: MudMenuPositionY): ConnectedPosition[] {
  const alignX = x === 'before' ? 'end' : 'start';
  const flipX = x === 'before' ? 'start' : 'end';
  const originY = y === 'above' ? 'top' : 'bottom';
  const overlayY = y === 'above' ? 'bottom' : 'top';
  const flipOriginY = y === 'above' ? 'bottom' : 'top';
  const flipOverlayY = y === 'above' ? 'top' : 'bottom';
  const offsetY = y === 'above' ? -4 : 4;

  return [
    { originX: alignX, originY, overlayX: alignX, overlayY, offsetY },
    { originX: alignX, originY: flipOriginY, overlayX: alignX, overlayY: flipOverlayY, offsetY: -offsetY },
    { originX: flipX, originY, overlayX: flipX, overlayY, offsetY },
    { originX: flipX, originY: flipOriginY, overlayX: flipX, overlayY: flipOverlayY, offsetY: -offsetY },
  ];
}

function submenuPositions(x: MudMenuPositionX): ConnectedPosition[] {
  const [originX, overlayX] = x === 'before' ? (['start', 'end'] as const) : (['end', 'start'] as const);
  const [flipOriginX, flipOverlayX] = x === 'before' ? (['end', 'start'] as const) : (['start', 'end'] as const);

  return [
    { originX, originY: 'top', overlayX, overlayY: 'top', offsetY: -8 },
    { originX: flipOriginX, originY: 'top', overlayX: flipOverlayX, overlayY: 'top', offsetY: -8 },
    { originX, originY: 'bottom', overlayX, overlayY: 'bottom', offsetY: 8 },
    { originX: flipOriginX, originY: 'bottom', overlayX: flipOverlayX, overlayY: 'bottom', offsetY: 8 },
  ];
}

/**
 * ```html
 * <button mudButton [mudMenuTriggerFor]="menu">Open</button>
 * ```
 */
@Directive({
  selector: '[mudMenuTriggerFor]',
  host: {
    '[attr.aria-haspopup]': "menu().type() === 'selection' ? 'listbox' : 'menu'",
    '[attr.aria-expanded]': '_isOpen()',
    '[attr.aria-controls]': '_isOpen() ? menu()._panelId : null',
    '(click)': '_onClick($event)',
    '(keydown)': '_onKeydown($event)',
    '(mouseenter)': '_onMouseEnter()',
    '(mouseleave)': '_onMouseLeave()',
  },
})
export class MudMenuTrigger implements MudMenuTriggerHandle {
  /** @description The mud-menu this trigger presents. */
  readonly menu = input.required<MudMenu>({ alias: 'mudMenuTriggerFor' });

  /** @description Fired when the overlay actually opens. */
  readonly opened = output<void>();

  /** @description Fired when the overlay actually closes. */
  readonly closed = output<void>();

  private readonly _overlay = inject(Overlay);
  private readonly _host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly _injector = inject(Injector);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  // On an item this resolves the CONTAINING menu (the panel the item lives in),
  // because MUD_MENU_PANEL is provided by MudMenu and projected content keeps
  // its declaration-site injector chain.
  private readonly _parentPanel = inject(MUD_MENU_PANEL, { optional: true });

  /** @docs-private Same-element item when this trigger opens a submenu. */
  readonly _hostItem = inject(MudMenuItem, { optional: true, self: true });

  /** @docs-private */
  readonly isSubmenu = this._hostItem !== null && this._parentPanel !== null;

  /** @docs-private Open submenu below this one, if any. */
  _childTrigger: MudMenuTriggerHandle | null = null;

  private _parentTrigger: MudMenuTriggerHandle | null = null;
  private _overlayRef: OverlayRef | null = null;
  private _outsideSub: Subscription | null = null;
  private _hoverTimer: ReturnType<typeof setTimeout> | null = null;

  /** @docs-private */
  readonly _isOpen = signal(false);

  constructor() {
    this._hostItem?._hasSubmenu.set(true);
    inject(DestroyRef).onDestroy(() => {
      this._clearHoverTimer();
      this.close(false);
    });
  }

  /** Opens the menu (no-op on the server, when already open, or when the parent chain already closed). */
  open(): void {
    if (!this._isBrowser || this._isOpen()) return;

    if (this.isSubmenu && !this._parentPanel?._attachedTrigger()) return;

    const menu = this.menu();
    const anchor = this._host.nativeElement;
    const positionStrategy = this._overlay
      .position()
      .flexibleConnectedTo(anchor)
      .withFlexibleDimensions(false)
      .withPush(false)
      .withViewportMargin(8)
      .withPositions(this.isSubmenu ? submenuPositions(menu.xPosition()) : rootPositions(menu.xPosition(), menu.yPosition()));

    this._overlayRef = this._overlay.create({
      positionStrategy,
      scrollStrategy: this._overlay.scrollStrategies.reposition(),
    });
    this._overlayRef.attach(new TemplatePortal(menu._panelTemplate(), menu._viewContainerRef));

    menu._attachedTrigger.set(this);
    this._parentTrigger = this._parentPanel?._attachedTrigger() ?? null;

    if (this._parentTrigger) {
      // Opening a sibling submenu supersedes the one already open.
      if (this._parentTrigger._childTrigger && this._parentTrigger._childTrigger !== this) {
        this._parentTrigger._childTrigger.close(false);
      }

      this._parentTrigger._childTrigger = this;
    }

    // Only the root of a chain watches outside interactions; clicks inside
    // descendant overlays count as inside via the chain walk.
    if (!this.isSubmenu) {
      this._outsideSub = this._overlayRef.outsidePointerEvents().subscribe((event) => {
        const target = event.target as Node | null;

        if (target && !this._containsEvent(target)) this.closeAll(false);
      });
    }

    this._isOpen.set(true);
    afterNextRender(() => menu._focusFirst(), { injector: this._injector });
    this.opened.emit();
  }

  /** Closes this level (descendants first); restoreFocus returns focus to the host. */
  close(restoreFocus: boolean): void {
    if (!this._isOpen()) return;

    this._clearHoverTimer();
    this._childTrigger?.close(false);
    this._childTrigger = null;
    this._outsideSub?.unsubscribe();
    this._outsideSub = null;
    this._overlayRef?.dispose();
    this._overlayRef = null;
    this.menu()._attachedTrigger.set(null);

    if (this._parentTrigger?._childTrigger === this) this._parentTrigger._childTrigger = null;

    this._parentTrigger = null;
    this._isOpen.set(false);

    if (restoreFocus) this._host.nativeElement.focus();

    this.closed.emit();
  }

  /** Closes the whole chain from its root. */
  closeAll(restoreFocus: boolean): void {
    if (this._parentTrigger) this._parentTrigger.closeAll(restoreFocus);
    else this.close(restoreFocus);
  }

  /** Toggles between open and closed. */
  toggle(): void {
    if (this._isOpen()) this.close(true);
    else this.open();
  }

  /** @docs-private True when the node lies inside this trigger, its overlay, or any descendant chain link. */
  _containsEvent(target: Node): boolean {
    if (this._host.nativeElement.contains(target)) return true;

    if (this._overlayRef?.overlayElement.contains(target)) return true;

    return this._childTrigger?._containsEvent(target) ?? false;
  }

  /** @docs-private Delayed close, cancelled by re-hovering (Task 5 wires callers). */
  _scheduleClose(): void {
    this._clearHoverTimer();
    this._hoverTimer = setTimeout(() => this.close(false), SUBMENU_HOVER_DELAY_MS);
  }

  protected _onClick(event: MouseEvent): void {
    if (this._hostItem?.disabled()) return;

    // stopPropagation doesn't affect MudMenuItem's own (click) on this same
    // element — same-element listeners fire regardless of propagation; the
    // real guard against double handling is _activate()'s _hasSubmenu()
    // early return. What this DOES stop is the click reaching an ANCESTOR
    // panel's keydown/click handling once nested (submenu) triggers exist.
    event.stopPropagation();
    this.toggle();
  }

  protected _onKeydown(event: KeyboardEvent): void {
    if (this.isSubmenu) {
      if (this._hostItem?.disabled()) return;

      if (event.key === 'ArrowRight' || event.key === 'Enter' || event.key === ' ') {
        event.preventDefault();
        event.stopPropagation();
        this.open();
      }

      return;
    }

    if (event.key === 'ArrowDown' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      this.open();
    } else if (event.key === 'ArrowUp') {
      event.preventDefault();
      this.open();
      afterNextRender(() => this.menu()._focusLast(), { injector: this._injector });
    }
  }

  protected _onMouseEnter(): void {
    if (!this.isSubmenu || this._hostItem?.disabled()) return;

    if (this._isOpen()) {
      this._clearHoverTimer();

      return;
    }

    this._clearHoverTimer();
    this._hoverTimer = setTimeout(() => this.open(), SUBMENU_HOVER_DELAY_MS);
  }

  protected _onMouseLeave(): void {
    // A pointer that merely crossed the item must not open the submenu later —
    // cancel the PENDING open only. An open submenu stays (the pointer is
    // usually heading into its panel); sibling-hover close owns that case.
    if (!this.isSubmenu || this._isOpen()) return;

    this._clearHoverTimer();
  }

  private _clearHoverTimer(): void {
    if (this._hoverTimer !== null) {
      clearTimeout(this._hoverTimer);
      this._hoverTimer = null;
    }
  }
}

import { Directive } from '@angular/core';
import { CdkPortal } from '@angular/cdk/portal';

/**
 * ```html
 * <mud-tab>
 *   <ng-template mudTabLabel>
 *     <mud-icon name="alarm" /> Alerts <span class="badge">3</span>
 *   </ng-template>
 *   …content…
 * </mud-tab>
 * ```
 *
 * Extends `CdkPortal` so the group can project it into the tab button.
 */
@Directive({ selector: '[mudTabLabel]' })
export class MudTabLabel extends CdkPortal {}

import {
  booleanAttribute,
  DestroyRef,
  Directive,
  DOCUMENT,
  effect,
  ElementRef,
  inject,
  input,
  numberAttribute,
  output,
  PLATFORM_ID,
  signal,
} from '@angular/core';
import type { ComponentRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Overlay } from '@angular/cdk/overlay';
import type { OverlayRef } from '@angular/cdk/overlay';
import { ComponentPortal } from '@angular/cdk/portal';
import { MudTooltipContainer } from './mud-tooltip-container.component';
import { connectedPositionsFor } from './tooltip-positions';
import type { MudTooltipPlacement, MudTooltipSize } from './tooltip-positions';

let nextUniqueId = 0;

export type MudTooltipTrigger = 'hover' | 'click' | 'focus' | 'manual';
export type MudTooltipVariant = 'default' | 'coach';
export type MudTooltipCloseReason =
  | 'blur'
  | 'escape'
  | 'close-button'
  | 'click-outside'
  | 'click-trigger';

/**
 * ```html
 * <button mudTooltip="Saved successfully!" tooltipPlacement="top-center" tooltipSize="large">
 *   Save
 * </button>
 * <button mudTooltip="Try the new filters here." tooltipVariant="coach" tooltipTitle="New!">
 *   Filters
 * </button>
 * ```
 */
@Directive({
  selector: '[mudTooltip]',
  exportAs: 'mudTooltip',
  host: {
    '(mouseenter)': 'onMouseEnter()',
    '(mouseleave)': 'onMouseLeave()',
    '(focus)': 'onFocus()',
    '(blur)': 'onBlur()',
    '(click)': 'onClick()',
  },
})
export class MudTooltip {
  private readonly _overlay = inject(Overlay);
  private readonly _trigger = inject(ElementRef<HTMLElement>).nativeElement;
  private readonly _document = inject(DOCUMENT);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  readonly mudTooltip = input.required<string>();
  readonly tooltipPlacement = input<MudTooltipPlacement>('top-center');
  readonly tooltipSize = input<MudTooltipSize>('small');
  /**
   * @description What opens the tooltip. `hover` also opens on focus; `manual`
   * only reacts to `show()`/`hide()`. Coach tooltips ignore hover/focus paths.
   */
  readonly tooltipTrigger = input<MudTooltipTrigger>('hover');
  /**
   * @description `coach` is the persistent onboarding bubble: it stays open until
   * Escape, the close button, or an outside click, and shows a hint line.
   */
  readonly tooltipVariant = input<MudTooltipVariant>('default');
  /** @description Optional bold title line rendered above the message. */
  readonly tooltipTitle = input<string | undefined>(undefined);
  /** @description Hint line shown by coach tooltips. Localize per app. */
  readonly tooltipCoachHint = input('Press Esc to close');
  /**
   * @description Keeps the bubble open while the pointer is over it (so links inside
   * stay reachable). Off by default, matching the official tooltip.
   */
  readonly tooltipInteractive = input(false, { transform: booleanAttribute });
  readonly tooltipCloseable = input(false, { transform: booleanAttribute });
  readonly tooltipDisabled = input(false, { transform: booleanAttribute });
  readonly tooltipMaxWidth = input('280px');
  readonly tooltipShowDelay = input(200, { transform: numberAttribute });
  readonly tooltipHideDelay = input(150, { transform: numberAttribute });
  readonly tooltipCloseAriaLabel = input('Close');

  /** Emitted when the tooltip closes for a user-initiated reason. */
  readonly tooltipDismissed = output<MudTooltipCloseReason>();

  private readonly _id = `mud-tooltip-${nextUniqueId++}`;

  private _overlayRef: OverlayRef | null = null;
  private readonly _containerRef = signal<ComponentRef<MudTooltipContainer> | null>(null);
  private _showTimeout: ReturnType<typeof setTimeout> | null = null;
  private _hideTimeout: ReturnType<typeof setTimeout> | null = null;
  private _pinned = false;

  /**
   * @description Registered in the capture phase (only while the tooltip is open) so a
   * consumed Escape closes just the tooltip, not an enclosing dialog too.
   * */
  private readonly _onDocumentKeydown = (event: KeyboardEvent): void => {
    if (event.key !== 'Escape') return;

    event.stopPropagation();
    this._dismiss('escape');
  };

  private get _isCoach(): boolean {
    return this.tooltipVariant() === 'coach';
  }

  /** Coach tooltips behave like click-triggered ones regardless of trigger. */
  private get _effectiveTrigger(): MudTooltipTrigger {
    return this._isCoach ? 'click' : this.tooltipTrigger();
  }

  constructor() {
    inject(DestroyRef).onDestroy(() => this._detach());

    /**
     * @description The attach-time setInput calls are one-shot snapshots; this keeps an
     * open tooltip in sync when its inputs change (e.g. "Copy" → "Copied!").
     * Placement stays attach-time - the position strategy is built from it.
     * */
    effect(() => {
      const container = this._containerRef();

      if (!container) return;

      container.setInput('message', this.mudTooltip());
      container.setInput('size', this.tooltipSize());
      container.setInput('closeable', this.tooltipCloseable() || this._isCoach);
      container.setInput('closeAriaLabel', this.tooltipCloseAriaLabel());
      container.setInput('maxWidth', this.tooltipMaxWidth());
      container.setInput('title', this.tooltipTitle());
      container.setInput('variant', this.tooltipVariant());
      container.setInput('coachHint', this.tooltipCoachHint());
    });
  }

  show(): void {
    if (this.tooltipDisabled()) return;

    this._clearTimeouts();
    this._attach();
    this._pinned = true;
  }

  hide(): void {
    this._detach();
  }

  protected onMouseEnter(): void {
    if (this._effectiveTrigger !== 'hover') return;

    this._scheduleShow(this.tooltipShowDelay());
  }

  protected onMouseLeave(): void {
    if (this._effectiveTrigger !== 'hover') return;

    this._scheduleHide();
  }

  protected onFocus(): void {
    const trigger = this._effectiveTrigger;

    if (trigger !== 'hover' && trigger !== 'focus') return;

    this._scheduleShow(0);
  }

  protected onBlur(): void {
    const trigger = this._effectiveTrigger;

    if (trigger !== 'hover' && trigger !== 'focus') return;

    this._scheduleHide();
  }

  protected onClick(): void {
    if (this.tooltipDisabled()) return;

    if (this._effectiveTrigger !== 'click') return;

    if (this._overlayRef?.hasAttached()) {
      this._dismiss('click-trigger');
    } else {
      this._clearTimeouts();
      this._attach();

      this._pinned = true;
    }
  }

  private _scheduleShow(delay: number): void {
    if (this.tooltipDisabled()) return;

    this._clearTimeouts();

    if (this._overlayRef?.hasAttached()) return;

    this._showTimeout = setTimeout(() => this._attach(), delay);
  }

  /**
   * @description Hides after the hide delay so the pointer can travel onto an
   * interactive bubble before it disappears.
   * */
  private _scheduleHide(): void {
    if (this._pinned) return;

    this._clearTimeouts();
    this._hideTimeout = setTimeout(() => this._dismiss('blur'), this.tooltipHideDelay());
  }

  private _attach(): void {
    /**
     * DOM events never fire during SSR, but show() may be called from app code
     * so we never build an overlay on the server.
     * */
    if (!this._isBrowser) return;

    if (this._overlayRef?.hasAttached()) return;

    const positions = connectedPositionsFor(this.tooltipPlacement());
    const positionStrategy = this._overlay
      .position()
      .flexibleConnectedTo(this._trigger)
      .withFlexibleDimensions(false)
      .withViewportMargin(8)
      .withPush(true)
      .withPositions(positions.map((p) => p.position));

    this._overlayRef = this._overlay.create({
      positionStrategy,
      scrollStrategy: this._overlay.scrollStrategies.close(),
    });

    /**
     * The close scroll strategy detaches the overlay behind our back, so the
     * trigger cleanup (aria-describedby, keydown listener, pinned state) must
     * follow every detachment, not only the ones this directive initiates.
     * */
    this._overlayRef.detachments().subscribe(() => this._detach());

    const containerRef: ComponentRef<MudTooltipContainer> = this._overlayRef.attach(
      new ComponentPortal(MudTooltipContainer),
    );

    containerRef.setInput('tooltipId', this._id);
    containerRef.setInput('message', this.mudTooltip());
    containerRef.setInput('placement', this.tooltipPlacement());
    containerRef.setInput('size', this.tooltipSize());
    containerRef.setInput('closeable', this.tooltipCloseable() || this._isCoach);
    containerRef.setInput('closeAriaLabel', this.tooltipCloseAriaLabel());
    containerRef.setInput('maxWidth', this.tooltipMaxWidth());
    containerRef.setInput('title', this.tooltipTitle());
    containerRef.setInput('variant', this.tooltipVariant());
    containerRef.setInput('coachHint', this.tooltipCoachHint());
    this._containerRef.set(containerRef);

    /**
     * When the preferred placement doesn't fit, CDK falls back to another
     * position — mirror the placement that actually applied so the arrow moves with it.
     * */
    positionStrategy.positionChanges.subscribe((change) => {
      const applied = positions.find((p) => p.position === change.connectionPair);

      if (applied) containerRef.setInput('placement', applied.placement);
    });

    containerRef.instance.closed.subscribe(() => this._dismiss('close-button'));

    // Hovering the bubble keeps it open only for interactive tooltips
    // (official behavior); otherwise leaving the trigger hides it.
    if (this.tooltipInteractive()) {
      containerRef.instance.hovered.subscribe((inside) => {
        if (inside) {
          this._clearTimeouts();
        } else {
          this._scheduleHide();
        }
      });
    }

    this._overlayRef.outsidePointerEvents().subscribe((event) => {
      const target = event.target as Node | null;

      if (this._pinned && target && !this._trigger.contains(target)) this._dismiss('click-outside');
    });

    this._pinned = this.tooltipCloseable() || this._isCoach;

    /**
     * aria-describedby is a token list the trigger may already use (form hints etc.)
     * append rather than replace, and remove only our own token again on detach.
     * */
    const describedby = this._trigger.getAttribute('aria-describedby');

    this._trigger.setAttribute(
      'aria-describedby',
      describedby ? `${describedby} ${this._id}` : this._id,
    );
    this._document.addEventListener('keydown', this._onDocumentKeydown, { capture: true });
  }

  private _dismiss(reason: MudTooltipCloseReason): void {
    if (!this._overlayRef?.hasAttached()) return;

    this._detach();
    this.tooltipDismissed.emit(reason);
  }

  private _detach(): void {
    this._clearTimeouts();
    this._pinned = false;
    this._containerRef.set(null);
    this._document.removeEventListener('keydown', this._onDocumentKeydown, { capture: true });

    const describedby = this._trigger.getAttribute('aria-describedby');

    if (describedby !== null) {
      const rest = describedby
        .split(/\s+/)
        .filter((token: string) => token && token !== this._id)
        .join(' ');

      if (rest) {
        this._trigger.setAttribute('aria-describedby', rest);
      } else {
        this._trigger.removeAttribute('aria-describedby');
      }
    }

    this._overlayRef?.dispose();
    this._overlayRef = null;
  }

  private _clearTimeouts(): void {
    if (this._showTimeout !== null) clearTimeout(this._showTimeout);

    if (this._hideTimeout !== null) clearTimeout(this._hideTimeout);

    this._showTimeout = null;
    this._hideTimeout = null;
  }
}

