    }
    .box--fill {
      background: var(--color-background-brand-secondary);
    }
    .box--outline {
      border-style: solid;
      border-color: var(--color-border-base-strong);
    }
    .box--thick {
      border-width: 3px;
    }
    .value {
      font-size: 0.72rem;
      color: var(--color-text-base-secondary);
    }
    .chip {
      display: inline-flex;
      align-items: center;
      justify-content: space-between;
      gap: 0.5rem;
      text-align: left;
      border: 1px solid var(--color-border-base-default);
