  color: var(--color-text-base-secondary);
}
.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: 0.75rem;
}
.swatch {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  position: relative;
  text-align: left;
  border: 1px solid var(--color-border-base-default);
