      margin: 0 0 1.5rem;
      font-size: 0.82rem;
      color: var(--color-text-base-secondary);
    }
    .note code {
      font-family: ui-monospace, monospace;
    }
    .grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
      gap: 0.75rem;
    }
    .card {
      display: flex;
      flex-direction: column;
      gap: 0.5rem;
      position: relative;
      text-align: left;
      border: 1px solid var(--color-border-base-default);
      border-radius: 10px;
      background: var(--color-background-base-default);
      padding: 0.75rem;
      font: inherit;
      cursor: pointer;
    }
    .card:hover {
      border-color: var(--color-border-base-secondary);
    }
    .demo {
      gap: 4px;
      align-content: flex-start;
      min-height: 72px;
      background: var(--color-background-base-secondary);
      border-radius: 8px;
      padding: 0.5rem;
      overflow: hidden;
    }
    .demo__box {
      display: block;
      width: 28px;
      height: 20px;
      border-radius: 4px;
      background: var(--color-background-brand-secondary-active);
      color: var(--color-text-base-inverse-on-color);
      font-size: 0.6rem;
      text-align: center;
      line-height: 20px;
    }
    .demo__hidden {
      font-size: 0.7rem;
      color: var(--color-text-base-tertiary);
    }
    .meta {
      display: flex;
      flex-direction: column;
      min-width: 0;
    }
    .meta__name {
      font-family: ui-monospace, monospace;
      font-size: 0.78rem;
    }
    .meta__value {
      font-size: 0.72rem;
      color: var(--color-text-base-secondary);
    }
    .copied {
      position: absolute;
      right: 0.6rem;
      top: 0.5rem;
      font-size: 0.7rem;
      color: var(--color-text-positive-default);
      opacity: 0;
      transition: opacity 0.15s;
    }
    .copied.show {
      opacity: 1;
    }
    .empty {
      color: var(--color-text-base-secondary);
    }
  `,
})
export class DisplayGridComponent {
  private readonly _document = inject(DOCUMENT);

  protected readonly utils = signal<DisplayUtil[]>([]);
  protected readonly copied = signal<string | null>(null);

  constructor() {
    afterNextRender(() => this._load());
  }

  protected copy(className: string): void {
    void navigator.clipboard?.writeText(className);
    this.copied.set(className);

    setTimeout(() => this.copied.update((current) => (current === className ? null : current)), 1200);
  }

  private _load(): void {
    const seen = new Set<string>();
    const utils: DisplayUtil[] = [];
    const singleClass = /^\.[a-z0-9-]+$/;

    for (const sheet of Array.from(this._document.styleSheets)) {
      let rules: CSSRuleList;

      try {
        rules = sheet.cssRules;
      } catch {
        continue;
      }

      for (const rule of Array.from(rules)) {
        if (!(rule instanceof CSSStyleRule) || !singleClass.test(rule.selectorText)) {
          continue;
        }

        const value = rule.style.getPropertyValue('display').trim();

        if (!value || rule.style.length !== 1) {
          continue;
        }

        const className = rule.selectorText.slice(1);

        if (!seen.has(className)) {
          seen.add(className);
          utils.push({ className, value });
        }
      }
    }

    utils.sort((a, b) => this._rank(a.value) - this._rank(b.value) || a.className.localeCompare(b.className));

    this.utils.set(utils);
  }

  private _rank(value: string): number {
    const index = ORDER.indexOf(value);

    return index === -1 ? ORDER.length : index;
  }
}

