@Component({
  imports: [MudTextInput, MudLabel, MudInlineMessage, ReactiveFormsModule],
  template: \`
    <mud-text-input required [formControl]="idnp" [invalid]="idnp.touched && idnp.invalid" [maxLength]="13">
      <mud-label>IDNP</mud-label>
