import {
  afterRenderEffect,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  DestroyRef,
  inject,
  input,
  linkedSignal,
  output,
  PLATFORM_ID,
  signal,
  viewChild,
} from '@angular/core';
import type { ElementRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { DomSanitizer } from '@angular/platform-browser';
import { FILE_GLYPH_SRC } from './file-glyph';

export type MudFileItemState = 'uploaded' | 'uploading' | 'success' | 'error';

export interface MudFileItemRemove {
  filename: string;
}

/**
 * Single-file row inside `mud-file-input`, or standalone in any file list
 * (consumer-driven upload progress, read-only summaries).
 *
 * ```html
 * <mud-file-item filename="raport.pdf" [size]="245760" state="uploading" />
 * ```
 *
 * Project an `[icon]` to replace the leading file glyph — a per-extension icon,
 * or an `<img ngSrc>` when the preview comes from a server (`previewSrc` mints
 * object URLs, which `NgOptimizedImage` rejects):
 *
 * ```html
 * <mud-file-item filename="raport.pdf">
 *   <mud-icon icon name="file-pdf" />
 * </mud-file-item>
 * ```
 *
 * A `previewSrc` thumbnail still wins over the projected icon, and the `error`
 * state drops the leading icon entirely so the status icon carries the row.
 */
@Component({
  selector: 'mud-file-item',
  templateUrl: './mud-file-item.component.html',
  host: {
    '[class]': '_hostClasses()',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudFileItem {
  /** @description Visible filename. Also suffixes the remove button's accessible label. */
  readonly filename = input.required<string>();

  /** @description File size in bytes, rendered human-readable (B / KB / MB / GB). */
  readonly size = input<number | undefined>(undefined);

  /**
   * @description Lifecycle state. `uploaded` (resting) and `error` rows are removable;
   * `uploading` shows a spinner and `success` a confirmation tick instead.
   */
  readonly state = input<MudFileItemState>('uploaded');

  /** @description Per-item error message, shown below the row only when `state` is `error`. */
  readonly errorText = input<string | undefined>(undefined);

  /**
   * @description Image-preview URL (object URL or data URI) rendered as a thumbnail in
   * place of the file glyph. Falls back to the glyph if the image fails to load.
   */
  readonly previewSrc = input<string | undefined>(undefined);

  /** @description Disables the remove button. */
  readonly disabled = input(false, { transform: booleanAttribute });

  /** @description Set false to hide the remove button entirely (read-only summary lists). */
  readonly removable = input(true, { transform: booleanAttribute });

  /** @description Accessible-label prefix of the remove button; the filename is appended. Localize per app. */
  readonly removeLabel = input('Remove file');

  /** Fired when the remove button is pressed. The owner splices the file out of its list. */
  readonly removed = output<MudFileItemRemove>();

  private readonly _filenameEl = viewChild<ElementRef<HTMLElement>>('filenameEl');
  private readonly _removeEl = viewChild<ElementRef<HTMLButtonElement>>('removeEl');
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  /**
   * @docs-private The glyph is our own constant; the bypass only exempts it from the
   * sanitizer's data-URI blocklist (`data:image/svg+xml` is not on Angular's
   * allowed image list), no untrusted value flows in.
   */
  protected readonly _glyphSrc = inject(DomSanitizer).bypassSecurityTrustUrl(FILE_GLYPH_SRC);

  /** @docs-private Cleared automatically when `previewSrc` changes to give the new image a chance. */
  protected readonly _previewFailed = linkedSignal(() => {
    this.previewSrc();

    return false;
  });

  /** @docs-private Gates the pure-CSS hover tooltip to actually-clipped filenames. */
  protected readonly _truncated = signal(false);

  protected readonly _showThumbnail = computed(() => !!this.previewSrc() && !this._previewFailed());

  /** @docs-private The error state drops the glyph so the red status icon carries the row alone. */
  protected readonly _showLeadingIcon = computed(() => this.state() !== 'error');

  protected readonly _showRemove = computed(
    () => this.removable() && (this.state() === 'uploaded' || this.state() === 'error'),
  );

  protected readonly _showErrorMessage = computed(
    () => this.state() === 'error' && !!this.errorText()?.trim(),
  );

  protected readonly _sizeText = computed(() => {
    const bytes = this.size();

    if (bytes === undefined) return '';

    if (bytes < 1024) return `${bytes} B`;

    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;

    if (bytes < 1024 * 1024 * 1024) return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;

    return `${(bytes / (1024 * 1024 * 1024)).toFixed(2)} GB`;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['file-item', `file-item--${this.state()}`];

    if (this.disabled()) classes.push('is-disabled');

    return classes.join(' ');
  });

  constructor() {
    if (!this._isBrowser || typeof ResizeObserver === 'undefined') return;

    const observer = new ResizeObserver(() => this._measureTruncation());

    inject(DestroyRef).onDestroy(() => observer.disconnect());

    afterRenderEffect(() => {
      this.filename();
      const el = this._filenameEl()?.nativeElement;

      observer.disconnect();

      if (!el) return;

      observer.observe(el);
      this._measureTruncation();
    });
  }

  private _measureTruncation(): void {
    const el = this._filenameEl()?.nativeElement;

    if (!el) return;

    this._truncated.set(el.scrollWidth > el.clientWidth + 1);
  }

  /**
   * @description Focuses this row's remove button. The owning list calls it after a
   * removal so focus never falls back to the document body.
   */
  focusRemove(): boolean {
    const button = this._removeEl()?.nativeElement;

    if (!this._isBrowser || !button || button.disabled) return false;

    button.focus();

    return true;
  }

  protected _onPreviewError(): void {
    this._previewFailed.set(true);
  }

  protected _onRemove(): void {
    if (this.disabled() || !this.removable()) return;

    this.removed.emit({ filename: this.filename() });
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  effect,
  inject,
  input,
} from '@angular/core';

declare const ngDevMode: boolean | undefined;

import type { SafeHtml } from '@angular/platform-browser';
import { DomSanitizer } from '@angular/platform-browser';
import { MudIconRegistry } from './mud-icon-registry.service';
import type { MudIcon, MudIconGeometry, MudIconScale, MudIconVariant } from './types';
import type { MudIconName } from './icon-name';

const SCALES: readonly MudIconScale[] = [12, 16, 20, 24];

@Component({
  selector: 'mud-icon',
  template: `<span style="display: inline-flex" [innerHTML]="svg()"></span>`,
  styles: `
    :host {
      display: inline-flex;
      line-height: 0;
    }
  `,
  host: {
    '[attr.role]': 'ariaLabel() ? "img" : null',
    '[attr.aria-label]': 'ariaLabel() ?? null',
    '[attr.aria-hidden]': 'ariaLabel() ? null : "true"',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudIconComponent {
  private readonly _registry = inject(MudIconRegistry);
  private readonly _sanitizer = inject(DomSanitizer);

  readonly name = input.required<MudIconName>();
  readonly variant = input<MudIconVariant>('outlined');
  readonly scale = input<MudIconScale>(24);
  readonly ariaLabel = input<string | undefined, string | undefined>(undefined, {
    alias: 'aria-label',
    transform: (value) => {
      const trimmed = value?.trim();

      return trimmed ? trimmed : undefined;
    },
  });

  private readonly _resolution = computed<{
    geometry: MudIconGeometry | undefined;
    warnings: readonly string[];
  }>(() => {
    const warnings: string[] = [];
    const icon = this._registry.get(this.name());

    if (!icon) {
      if (typeof ngDevMode === 'undefined' || ngDevMode) {
        warnings.push(
          `[mud-icon] Icon "${this.name()}" is not registered. Did you call provideMudIcons([...])?`,
        );
      }

      return { geometry: undefined, warnings };
    }

    const variant = this._pickVariant(icon.variants, warnings);

    if (!variant) return { geometry: undefined, warnings };

    const byScale = icon.variants[variant]!;
    const scale = this._pickScale(byScale, warnings);

    if (scale === undefined) return { geometry: undefined, warnings };

    return { geometry: byScale[scale], warnings };
  });

  protected readonly svg = computed<SafeHtml>(() => {
    const geometry = this._resolution().geometry;

    if (!geometry) return '';

    const px = this.scale();
    const markup =
      `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${geometry.viewBox}" ` +
      `width="${px}" height="${px}" fill="currentColor" focusable="false" aria-hidden="true">` +
      `${geometry.body}</svg>`;

    return this._sanitizer.bypassSecurityTrustHtml(markup);
  });

  constructor() {
    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      for (const warning of this._resolution().warnings) console.warn(warning);
    });
  }

  private _pickVariant(
    variants: MudIcon['variants'],
    warnings: string[],
  ): MudIconVariant | undefined {
    const want = this.variant();

    if (variants[want]) return want;

    if (variants.outlined) {
      if (typeof ngDevMode === 'undefined' || ngDevMode) {
        warnings.push(`[mud-icon] "${this.name()}" has no "${want}" variant; using "outlined".`);
      }

      return 'outlined';
    }

    return (Object.keys(variants) as MudIconVariant[])[0];
  }

  private _pickScale(
    byScale: Partial<Record<MudIconScale, MudIconGeometry>>,
    warnings: string[],
  ): MudIconScale | undefined {
    const want = this.scale();

    if (byScale[want]) return want;

    const available = SCALES.filter((s) => byScale[s]);

    if (available.length === 0) return undefined;

    const larger = available.filter((s) => s > want).sort((a, b) => a - b)[0];
    const chosen = larger ?? available.filter((s) => s < want).sort((a, b) => b - a)[0];

    if (typeof ngDevMode === 'undefined' || ngDevMode) {
      warnings.push(`[mud-icon] "${this.name()}" has no scale ${want}; using ${chosen}.`);
    }

    return chosen;
  }
}

import {
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChildren,
  forwardRef,
  inject,
  input,
} from '@angular/core';

declare const ngDevMode: boolean | undefined;

/**
 * One entry of an {@link MudStepIndicator}. Projected content renders
 * under the heading as supporting text and/or an action.
 */
@Component({
  selector: 'mud-indicator-step',
  template: `
    <span class="indicator-step__connector" aria-hidden="true"></span>
    <span class="indicator-step__circle" aria-hidden="true">{{ _number() }}</span>
    <div class="indicator-step__body">
      <span class="indicator-step__heading">{{ heading() }}</span>
      <div class="indicator-step__content"><ng-content /></div>
    </div>
  `,
  host: {
    class: 'indicator-step',
    role: 'listitem',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudIndicatorStep {
  private readonly _indicator = inject<MudStepIndicator>(forwardRef(() => MudStepIndicator));

  readonly heading = input.required<string>();

  private _warnedNotFound = false;

  protected readonly _number = computed(() => {
    const index = this._indicator.steps().indexOf(this);

    if (index === -1) {
      if ((typeof ngDevMode === 'undefined' || ngDevMode) && !this._warnedNotFound) {
        this._warnedNotFound = true;
        console.warn(
          'mud-indicator-step: not found among the direct children of mud-step-indicator; ' +
            'the step cannot be numbered. Do not wrap mud-indicator-step in another element.',
        );
      }

      return null;
    }

    return index + 1;
  });
}

/**
 * ```html
 * <mud-step-indicator>
 *   <mud-indicator-step heading="Create account">
 *     Supporting text
 *     <button mud-button>Start</button>
 *   </mud-indicator-step>
 * </mud-step-indicator>
 * ```
 */
@Component({
  selector: 'mud-step-indicator',
  template: '<ng-content />',
  host: {
    class: 'step-indicator',
    role: 'list',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudStepIndicator {
  readonly steps = contentChildren(MudIndicatorStep);
}

