import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  contentChildren,
  effect,
  forwardRef,
  inject,
  input,
  model,
  numberAttribute,
  output,
  PLATFORM_ID,
  signal,
  untracked,
  viewChild,
} from '@angular/core';
import type { ElementRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import type { ControlValueAccessor } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';

export type MudNumericInputVariant = 'default' | 'warning' | 'destructive' | 'success';
export type MudNumericInputSize = 'medium' | 'large';
export type MudNumericInputErrorKind = 'not-a-number' | 'out-of-range';

export interface MudNumericInputStep {
  value: number;
  direction: 1 | -1;
}

let nextUniqueId = 0;

/**
 * ```html
 * <mud-numeric-input [formField]="form.amount" required>
 *   <mud-label>Suma</mud-label>
 *   <span suffix>MDL</span>
 *   @if (form.amount().touched() && form.amount().invalid()) {
 *     <mud-inline-message variant="error">Suma este obligatorie.</mud-inline-message>
 *   }
 * </mud-numeric-input>
 * ```
 */
@Component({
  selector: 'mud-numeric-input',
  templateUrl: './mud-numeric-input.component.html',
  host: {
    '[class]': '_hostClasses()',
    '[attr.aria-busy]': "loading() ? 'true' : null",
  },
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MudNumericInput),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudNumericInput implements ControlValueAccessor, FormValueControl<number | null> {
  /** @description Color treatment. `destructive` is forced when `invalid` is set. */
  readonly variant = input<MudNumericInputVariant>('default');

  /** @description Size rung: medium (40px) or large (48px). */
  readonly size = input<MudNumericInputSize>('medium');

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });

  /** @description Destructive visuals + `aria-invalid`. Signal forms bind this automatically. */
  readonly invalid = input(false, { transform: booleanAttribute });

  /** @description Loading: uninteractive with a trailing spinner (replaces steppers/clear). */
  readonly loading = input(false, { transform: booleanAttribute });

  /** @description Current value (null while empty). Two-way bindable; driven by both forms systems. */
  readonly value = model<number | null>(null);

  /** @description Lower bound; commits clamp to it, steppers stop at it. Signal forms bind it. */
  readonly min = input<number | undefined>(undefined);

  /** @description Upper bound; commits clamp to it, steppers stop at it. Signal forms bind it. */
  readonly max = input<number | undefined>(undefined);

  /** @description Stepper / arrow-key increment. */
  readonly step = input(1, { transform: numberAttribute });

  /** @description Fraction digits commits are rounded (and formatted) to. */
  readonly precision = input<number | undefined>(undefined);

  /** @description Shows the trailing +/- stepper pair. */
  readonly showSteppers = input(false, { transform: booleanAttribute });

  /** @description When false, the decimal separator is blocked and commits truncate fractions. */
  readonly allowDecimal = input(true, { transform: booleanAttribute });

  /** @description When false, the minus sign is blocked and negative commits clamp up. */
  readonly allowNegative = input(true, { transform: booleanAttribute });

  /**
   * @description BCP 47 locale for display formatting and lenient parsing of grouped
   * input (e.g. ro-MD renders 1250.5 as "1.250,5"). Unset = plain digits with
   * a dot decimal separator.
   */
  readonly locale = input<string | undefined>(undefined);

  /** @description Shows a trailing clear (×) while the field holds a value. */
  readonly clearable = input(false, { transform: booleanAttribute });

  readonly name = input<string>('');
  readonly placeholder = input<string | undefined>(undefined);
  readonly maxLength = input<number | undefined>(undefined);

  /** @description Shows the `n / max` character counter while `maxLength` is set. */
  readonly showCounter = input(true, { transform: booleanAttribute });

  /** @description Optional consumer-owned screen-reader sentence for the counter. */
  readonly counterLabel = input<string | undefined>(undefined);

  /** @description Accessible label of the increment stepper. Localize per app. */
  readonly incrementLabel = input('Increase');

  /** @description Accessible label of the decrement stepper. Localize per app. */
  readonly decrementLabel = input('Decrease');

  /** @description Accessible label of the clear button. Localize per app. */
  readonly clearLabel = input('Clear');

  /** @description Accessible name used when no `mud-label` is projected. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description Human-friendly value announcement (native aria-valuetext). */
  readonly ariaValuetext = input<string | undefined>(undefined);

  /** @description Extra id(s) merged into the native control's aria-describedby. */
  readonly ariaDescribedby = input<string | undefined>(undefined, { alias: 'aria-describedby' });

  /** Fired when a stepper or arrow key changes the value. */
  readonly stepped = output<MudNumericInputStep>();

  /** Fired when typed input is rejected or clamped at parse/commit time. */
  readonly errored = output<MudNumericInputErrorKind>();

  /** Signal-forms touch contract: emitted when focus leaves the control. */
  readonly touch = output<void>();

  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());

  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-numeric-input-${nextUniqueId++}`;
  protected readonly _labelId = `${this._id}-label`;
  protected readonly _assistiveId = `${this._id}-assistive`;
  protected readonly _counterId = `${this._id}-counter`;

  protected readonly _focused = signal(false);

  /** @docs-private What the user sees; lenient while typing, formatted on commit. */
  protected readonly _display = signal('');

  private readonly _cvaDisabled = signal(false);
  private _onChange: (value: number | null) => void = () => undefined;
  private _onTouched: () => void = () => undefined;

  /** @docs-private Input + forms-driven disabled state combined. */
  protected readonly _effectiveDisabled = computed(() => this.disabled() || this._cvaDisabled());

  protected readonly _effectiveInvalid = computed(() => this.invalid());

  protected readonly _effectiveVariant = computed<MudNumericInputVariant>(() =>
    this._effectiveInvalid() ? 'destructive' : this.variant(),
  );

  protected readonly _inert = computed(
    () => this._effectiveDisabled() || this.readonly() || this.loading(),
  );

  protected readonly _inputMode = computed(() => (this.allowDecimal() ? 'decimal' : 'numeric'));

  protected readonly _canIncrement = computed(() => {
    if (this._inert()) return false;

    const max = this.max();

    return max === undefined || (this.value() ?? -Infinity) < max;
  });

  protected readonly _canDecrement = computed(() => {
    if (this._inert()) return false;

    const min = this.min();

    return min === undefined || (this.value() ?? Infinity) > min;
  });

  protected readonly _showCounter = computed(() => this.showCounter() && this.maxLength() != null);

  protected readonly _showClear = computed(
    () => this.clearable() && !this._inert() && this._display().length > 0,
  );

  protected readonly _describedBy = computed<string | null>(() => {
    const ids: string[] = [];

    if (this._hasMessages()) ids.push(this._assistiveId);

    if (this._showCounter()) ids.push(this._counterId);

    const external = this.ariaDescribedby()?.trim();

    if (external) ids.push(external);

    return ids.length > 0 ? ids.join(' ') : null;
  });

  protected readonly _ariaLabel = computed<string | null>(() => {
    if (this._hasLabel()) return null;

    return this.ariaLabel() ?? null;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['input-field', 'numeric-field', `input-field--${this._effectiveVariant()}`];

    if (this.size() === 'large') classes.push('input-field--lg');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this.readonly()) classes.push('is-readonly');

    if (this.loading()) classes.push('is-loading');

    if (this._effectiveInvalid()) classes.push('is-invalid');

    if (this._focused() && !this._effectiveDisabled()) classes.push('is-focused');

    return classes.join(' ');
  });

  constructor() {
    // External value changes (writeValue, [(value)], signal forms) reformat
    // the display. While focused, a change that merely echoes the user's own
    // typing (model === parse(display)) must NOT reformat mid-entry; a
    // genuinely different programmatic value still wins.
    effect(() => {
      const value = this.value();

      // Untracked: the display must not re-trigger this effect (typing a
      // partial like "abc" or "1," would otherwise be clobbered instantly).
      const typedValue = untracked(() => this._parse(this._display()));

      if (untracked(this._focused) && Object.is(typedValue, value)) return;

      untracked(() => this._display.set(this._format(value)));
    });
  }

  // ----- ControlValueAccessor (reactive/template-driven forms) -----

  writeValue(value: number | null | undefined): void {
    this.value.set(value ?? null);
  }

  registerOnChange(fn: (value: number | null) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  // ----- FormValueControl extras -----

  /** Focuses the native input (also used by signal forms' focus requests). */
  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  // ----- parsing / formatting -----

  private _separators(): { group: string; decimal: string } {
    const locale = this.locale();

    if (!locale) return { group: '', decimal: '.' };

    const parts = new Intl.NumberFormat(locale).formatToParts(12345.6);

    return {
      group: parts.find((part) => part.type === 'group')?.value ?? '',
      decimal: parts.find((part) => part.type === 'decimal')?.value ?? '.',
    };
  }

  private _parse(raw: string): number | null {
    const trimmed = raw.trim();

    if (!trimmed) return null;

    const { group, decimal } = this._separators();
    let normalized = trimmed;

    if (group) normalized = normalized.split(group).join('');

    if (decimal !== '.') normalized = normalized.split(decimal).join('.');

    const value = Number(normalized);

    return Number.isFinite(value) ? value : null;
  }

  private _format(value: number | null): string {
    if (value === null) return '';

    const locale = this.locale();
    const precision = this.precision();

    if (!locale) {
      return precision !== undefined ? value.toFixed(precision) : String(value);
    }

    return new Intl.NumberFormat(locale, {
      minimumFractionDigits: precision ?? 0,
      maximumFractionDigits: precision ?? (this.allowDecimal() ? 20 : 0),
      useGrouping: true,
    }).format(value);
  }

  private _clampAndRound(value: number): number {
    let next = value;

    if (!this.allowDecimal()) next = Math.trunc(next);

    const min = this.min();
    const max = this.max();

    if (!this.allowNegative() && next < 0) next = Math.max(0, min ?? 0);

    if (min !== undefined && next < min) next = min;

    if (max !== undefined && next > max) next = max;

    const precision = this.precision();

    if (precision !== undefined) {
      const factor = 10 ** precision;

      next = Math.round(next * factor) / factor;
    }

    return next;
  }

  // ----- handlers -----

  protected _onKeydown(event: KeyboardEvent): void {
    if (this._inert()) return;

    const { decimal } = this._separators();

    switch (event.key) {
      case 'ArrowUp':
        event.preventDefault();
        this._stepBy(1);

        return;
      case 'ArrowDown':
        event.preventDefault();
        this._stepBy(-1);

        return;
      case 'Home':
        if (this.min() !== undefined) {
          event.preventDefault();
          this._setCommitted(this.min()!);
        }

        return;
      case 'End':
        if (this.max() !== undefined) {
          event.preventDefault();
          this._setCommitted(this.max()!);
        }

        return;
      case 'Enter':
        this._commit();

        return;
    }

    if (!this.allowDecimal() && (event.key === '.' || event.key === decimal)) {
      event.preventDefault();
    }

    if (!this.allowNegative() && event.key === '-') {
      event.preventDefault();
    }
  }

  protected _onInput(event: Event): void {
    const raw = (event.target as HTMLInputElement).value;

    this._display.set(raw);

    const parsed = this._parse(raw);

    if (raw.trim() && parsed === null) return; // partial entry ("-", "1,")

    if (parsed !== null) {
      const min = this.min();
      const max = this.max();

      if ((min !== undefined && parsed < min) || (max !== undefined && parsed > max)) {
        this.errored.emit('out-of-range');
      }
    }

    this.value.set(parsed);
    this._onChange(parsed);
  }

  /** Parses the display, clamps + rounds, updates the model, reformats. */
  protected _commit(): void {
    const raw = this._display();
    const parsed = this._parse(raw);

    if (raw.trim() && parsed === null) {
      this.errored.emit('not-a-number');
      this._display.set(this._format(this.value() === null ? null : this._clampAndRound(this.value()!)));

      return;
    }

    if (parsed === null) {
      this.value.set(null);
      this._onChange(null);
      this._display.set('');

      return;
    }

    const committed = this._clampAndRound(parsed);

    if (committed !== parsed) this.errored.emit('out-of-range');

    this._setCommitted(committed);
  }

  private _setCommitted(value: number): void {
    const committed = this._clampAndRound(value);

    this.value.set(committed);
    this._onChange(committed);
    this._display.set(this._format(committed));
  }

  protected _stepBy(direction: 1 | -1): void {
    if (direction > 0 && !this._canIncrement()) return;

    if (direction < 0 && !this._canDecrement()) return;

    const base = this.value() ?? this.min() ?? 0;
    const committed = this._clampAndRound(base + direction * this.step());

    this.value.set(committed);
    this._onChange(committed);
    this._display.set(this._format(committed));
    this.stepped.emit({ value: committed, direction });
  }

  protected _onFocus(): void {
    this._focused.set(true);
  }

  protected _onBlur(): void {
    this._focused.set(false);
    this._commit();
    this._onTouched();
    this.touch.emit();
  }

  protected _onClear(): void {
    if (this._inert()) return;

    this.value.set(null);
    this._onChange(null);
    this._display.set('');
    this.focus();
  }
}

import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  contentChildren,
  effect,
  forwardRef,
  inject,
  input,
  model,
  output,
  PLATFORM_ID,
  LOCALE_ID,
  signal,
  untracked,
  viewChild,
} from '@angular/core';
import type { ElementRef, TemplateRef } from '@angular/core';
import { ViewContainerRef } from '@angular/core';
import { isPlatformBrowser } from '@angular/common';
import { Overlay } from '@angular/cdk/overlay';
import type { OverlayRef } from '@angular/cdk/overlay';
import { TemplatePortal } from '@angular/cdk/portal';
import { DomSanitizer } from '@angular/platform-browser';
import type { SafeUrl } from '@angular/platform-browser';
import { NG_VALUE_ACCESSOR } from '@angular/forms';
import type { ControlValueAccessor } from '@angular/forms';
import type { FormValueControl } from '@angular/forms/signals';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';
import {
  MUD_PHONE_COUNTRIES,
  MUD_PHONE_DEFAULT_ISO,
  findCountry,
  findCountryByDialCode,
  validateCountry,
} from './phone-countries';
import type { MudPhoneCountry } from './phone-countries';
import { MUD_PHONE_FLAGS } from './phone-flags';
import { MUD_PHONE_COUNTRIES_CONFIG } from './provide-mud-phone-countries';
import { applyMask, caretForDigitIndex, digitsBefore, digitsOf, isComplete, nationalOf, toE164 } from './phone-mask';

declare const ngDevMode: boolean | undefined;

export type MudPhoneInputSize = 'medium' | 'large';
export type MudPhoneInputVariant = 'default' | 'warning' | 'destructive' | 'success';

export type MudPhoneInputMode = 'local' | 'international';

export interface MudPhoneInputChange {
  /** Canonical E.164, or the empty string when no digits were entered. */
  value: string;
  /** ISO 3166-1 alpha-2 of the country the number was entered against. */
  country: string;
  /** Whether the national digit count sits inside the country's window. */
  complete: boolean;
}

let nextUniqueId = 0;

/**
 * Phone entry with a country dial-code prefix and a per-country format mask.
 * The form value is canonical E.164 (`+37362123456`); the masked national
 * segment is only ever a rendering of it.
 *
 * ```html
 * <mud-phone-input [formField]="form.phone" required>
 *   <mud-label>Telefon</mud-label>
 *   @if (form.phone().touched() && form.phone().invalid()) {
 *     <mud-inline-message variant="error">Număr invalid.</mud-inline-message>
 *   }
 * </mud-phone-input>
 * ```
 */
@Component({
  selector: 'mud-phone-input',
  templateUrl: './mud-phone-input.component.html',
  host: {
    '[class]': '_hostClasses()',
  },
  providers: [
    {
      provide: NG_VALUE_ACCESSOR,
      useExisting: forwardRef(() => MudPhoneInput),
      multi: true,
    },
  ],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudPhoneInput implements ControlValueAccessor, FormValueControl<string> {
  /** @description Canonical E.164 (`+37362123456`). */
  readonly value = model<string>('');

  /**
   * @description Selected country as ISO 3166-1 alpha-2. Two-way: writing an E.164 whose
   * dial code belongs to another country moves it. Unknown codes warn in dev
   * and fall back to Moldova.
   */
  readonly country = model<string>(MUD_PHONE_DEFAULT_ISO);

  /**
   * @description `local` (default) fixes the country to `country` and renders its prefix
   * as inert text. `international` renders a combobox that opens a searchable
   * country list.
   */
  readonly mode = input<MudPhoneInputMode>('local');

  /**
   * @description The countries to offer in `international` mode, in this order. Defaults
   * to the full curated list.
   *
   * Entries are either an ISO code from the built-in table (`'RO'`) or a whole
   * `MudPhoneCountry` object, which is how you add a country the table does not
   * carry. Unknown ISO codes and malformed objects warn in development.
   */
  readonly countries = input<readonly (string | MudPhoneCountry)[] | undefined>(undefined);

  /**
   * @description BCP 47 locale the country names are rendered in. Defaults to the app's
   * `LOCALE_ID`. Names come from `Intl.DisplayNames`, so no per-language data
   * ships with the component.
   */
  readonly locale = input<string | undefined>(undefined);

  /** @description Size rung: medium (40px) or large (48px). */
  readonly size = input<MudPhoneInputSize>('medium');

  /** @description Colour treatment. `destructive` is forced when `invalid` is set. */
  readonly variant = input<MudPhoneInputVariant>('default');

  readonly disabled = input(false, { transform: booleanAttribute });
  readonly required = input(false, { transform: booleanAttribute });
  readonly readonly = input(false, { transform: booleanAttribute });

  /** @description Destructive visuals + `aria-invalid`. Signal forms bind this automatically. */
  readonly invalid = input(false, { transform: booleanAttribute });

  /** @description Shows a trailing clear button while the field holds digits. */
  readonly clearable = input(false, { transform: booleanAttribute });

  readonly name = input<string>('');

  /** @description Placeholder for the national segment. Defaults to the country's mask. */
  readonly placeholder = input<string | undefined>(undefined);

  /** @description Accessible label of the clear button. Localize per app. */
  readonly clearLabel = input('Clear');

  /** @description Accessible name of the country combobox. Localize per app. */
  readonly countryLabel = input('Country');

  /** @description Placeholder and accessible name of the country search field. Localize per app. */
  readonly countrySearchLabel = input('Search country');

  /** @description Shown in the country list when the search matches nothing. Localize per app. */
  readonly countryEmptyText = input('No countries found');

  /** @description Accessible name used when no `mud-label` is projected. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  /** @description Extra id(s) merged into the native control's aria-describedby. */
  readonly ariaDescribedby = input<string | undefined>(undefined, { alias: 'aria-describedby' });

  /** Fired when the value is committed (blur), carrying the digit-window check. */
  readonly changed = output<MudPhoneInputChange>();

  /** Signal-forms touch contract: emitted when the field loses focus. */
  readonly touch = output<void>();

  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');
  private readonly _control = viewChild.required<ElementRef<HTMLElement>>('control');
  private readonly _trigger = viewChild<ElementRef<HTMLButtonElement>>('trigger');
  private readonly _searchEl = viewChild<ElementRef<HTMLInputElement>>('searchEl');
  private readonly _panelTemplate = viewChild<TemplateRef<unknown>>('panel');
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));
  private readonly _sanitizer = inject(DomSanitizer);
  private readonly _overlay = inject(Overlay);
  private readonly _viewContainerRef = inject(ViewContainerRef);
  /** App-wide list from `provideMudPhoneCountries`; the input outranks it. */
  private readonly _configuredCountries = inject(MUD_PHONE_COUNTRIES_CONFIG, { optional: true });
  private readonly _appLocale = inject(LOCALE_ID);

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());

  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-phone-input-${nextUniqueId++}`;
  protected readonly _labelId = `${this._id}-label`;
  protected readonly _assistiveId = `${this._id}-assistive`;
  protected readonly _listBoxId = `${this._id}-listbox`;
  protected readonly _triggerId = `${this._id}-country`;

  protected readonly _focused = signal(false);

  /** @docs-private Country-list state (international mode only). */
  protected readonly _open = signal(false);
  protected readonly _query = signal('');
  protected readonly _highlighted = signal(-1);

  private _overlayRef: OverlayRef | null = null;

  private readonly _cvaDisabled = signal(false);
  private _onChange: (value: string) => void = () => undefined;
  private _onTouched: () => void = () => undefined;

  /** Last E.164 this component itself wrote — anything else is an external write. */
  private _selfPublished: string | null = null;
  /** ISO the previous reconciliation saw, to detect an actual country change. */
  private _previousIso: string | undefined = undefined;
  /** A country this component moved by inference; its rebuild must be skipped. */
  private _skipRebuildFor: string | null = null;

  /** @docs-private Resolved country, always a real entry — never undefined. */
  protected readonly _country = computed<MudPhoneCountry>(() => {
    const iso = this.country()?.toUpperCase();
    const offered = this._countryList();

    return (
      offered.find((entry) => entry.iso.toUpperCase() === iso) ??
      offered[0] ??
      findCountry(MUD_PHONE_DEFAULT_ISO)!
    );
  });

  /**
   * @docs-private The masked national segment is a PURE derivation of the value and
   * country — no separate display state, so there is no sync effect to get
   * wrong (contrast the numeric-input display bridge).
   */
  protected readonly _display = computed(() =>
    applyMask(nationalOf(this.value(), this._country()), this._country()),
  );

  protected readonly _effectiveDisabled = computed(() => this.disabled() || this._cvaDisabled());

  protected readonly _effectiveInvalid = computed(() => this.invalid());

  protected readonly _effectiveVariant = computed<MudPhoneInputVariant>(() =>
    this._effectiveInvalid() ? 'destructive' : this.variant(),
  );

  /**
   * Trusted-URL cache: bypassing per render would allocate on every CD pass.
   * Keyed on the flag ITSELF, not the ISO - a supplied entry may override a
   * built-in country's flag, and an ISO key would keep serving the old one.
   */
  private readonly _flagCache = new Map<string, SafeUrl>();

  /** @docs-private Flag for any country row; memoized per ISO. */
  protected _flagFor(country: MudPhoneCountry): SafeUrl | null {
    const flag = country.flag ?? MUD_PHONE_FLAGS[country.iso];

    if (!flag) return null;

    const cached = this._flagCache.get(flag);

    if (cached) return cached;

    const trusted = this._sanitizer.bypassSecurityTrustUrl(flag);

    this._flagCache.set(flag, trusted);

    return trusted;
  }

  protected readonly _flagSrc = computed<SafeUrl | null>(() => this._flagFor(this._country()));

  /** @docs-private The offered countries, narrowed and ordered by `countries`. */
  protected readonly _activeLocale = computed(() => this.locale() ?? this._appLocale);

  /** `Intl.DisplayNames` is not cheap to construct; one per locale is plenty. */
  private readonly _displayNamesCache = new Map<string, Intl.DisplayNames | null>();

  /**
   * Resolved names, keyed by locale + ISO + fallback. `_countryName` is called
   * once per row per change-detection pass and once per row per search
   * keystroke, and `of()` is not free.
   */
  private readonly _countryNameCache = new Map<string, string>();

  private _displayNames(locale: string): Intl.DisplayNames | null {
    if (this._displayNamesCache.has(locale)) return this._displayNamesCache.get(locale)!;

    let instance: Intl.DisplayNames | null = null;

    try {
      if (typeof Intl?.DisplayNames === 'function') {
        instance = new Intl.DisplayNames([locale], { type: 'region' });
      }
    } catch {
      instance = null;
    }

    this._displayNamesCache.set(locale, instance);

    return instance;
  }

  /**
   * @docs-private The displayed country name, derived from the ISO code in the active
   * locale. `of()` echoes the code back when it has no data, which is not a
   * usable label, so that falls through to the entry's own `name`.
   */
  protected _countryName(country: MudPhoneCountry): string {
    const locale = this._activeLocale();
    const key = `${locale}|${country.iso}|${country.name}`;
    const cached = this._countryNameCache.get(key);

    if (cached !== undefined) return cached;

    const localized = this._displayNames(locale)?.of(country.iso);
    // `of()` echoes the code back when it has no data, which is not a label.
    const resolved =
      localized && localized.toUpperCase() !== country.iso.toUpperCase() ? localized : country.name;

    this._countryNameCache.set(key, resolved);

    return resolved;
  }

  /**
   * Resolution kept PURE - it returns the diagnostics rather than logging them,
   * so the computed has no side effects. An effect below does the warning.
   */
  private readonly _resolvedCountries = computed<{
    readonly list: readonly MudPhoneCountry[];
    readonly problems: readonly string[];
  }>(() => {
    const requested = this.countries() ?? this._configuredCountries;

    if (!requested) return { list: MUD_PHONE_COUNTRIES, problems: [] };

    const list: MudPhoneCountry[] = [];
    const problems: string[] = [];

    for (const entry of requested) {
      if (typeof entry !== 'string') {
        if (typeof ngDevMode === 'undefined' || ngDevMode) {
          const issues = validateCountry(entry);

          if (issues.length > 0) {
            problems.push(
              `country "${entry.iso}" supplied via [countries] looks wrong: ${issues.join('; ')}.`,
            );
          }
        }

        list.push(entry);
        continue;
      }

      const known = findCountry(entry);

      if (known) {
        list.push(known);
        continue;
      }

      if (typeof ngDevMode === 'undefined' || ngDevMode) {
        problems.push(
          `[countries] entry "${entry}" is not in the built-in table and was skipped. ` +
            `Pass a full MudPhoneCountry object to add a country the table does not carry.`,
        );
      }
    }

    return { list, problems };
  });

  protected readonly _countryList = computed<readonly MudPhoneCountry[]>(
    () => this._resolvedCountries().list,
  );

  /** @docs-private Search matches English name, Romanian name, ISO or dial code. */
  protected readonly _filtered = computed<readonly MudPhoneCountry[]>(() => {
    const query = this._query().trim().toLowerCase();

    if (!query) return this._countryList();

    const digits = query.replace(/\D/g, '');

    return this._countryList().filter((country) => {
      const haystack = [this._countryName(country), country.name, ...(country.aliases ?? [])];

      return (
        haystack.some((term) => term.toLowerCase().includes(query)) ||
        country.iso.toLowerCase() === query ||
        (!!digits && country.dialCode.replace(/\D/g, '').startsWith(digits))
      );
    });
  });

  protected readonly _activeDescendant = computed<string | null>(() => {
    const index = this._highlighted();

    return index >= 0 && index < this._filtered().length ? `${this._listBoxId}-opt-${index}` : null;
  });

  protected readonly _isInternational = computed(() => this.mode() === 'international');

  protected readonly _showClear = computed(
    () =>
      this.clearable() &&
      !this._effectiveDisabled() &&
      !this.readonly() &&
      this._display().length > 0,
  );

  protected readonly _describedBy = computed<string | null>(() => {
    const ids: string[] = [];

    if (this._hasMessages()) ids.push(this._assistiveId);

    const external = this.ariaDescribedby()?.trim();

    if (external) ids.push(external);

    return ids.length > 0 ? ids.join(' ') : null;
  });

  protected readonly _ariaLabel = computed<string | null>(() =>
    this._hasLabel() ? null : (this.ariaLabel() ?? null),
  );

  protected readonly _hostClasses = computed(() => {
    const classes = ['input-field', 'phone-field', `input-field--${this._effectiveVariant()}`];

    if (this.size() === 'large') classes.push('input-field--lg');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this.readonly()) classes.push('is-readonly');

    if (this._effectiveInvalid()) classes.push('is-invalid');

    if (this._focused() && !this._effectiveDisabled()) classes.push('is-focused');

    return classes.join(' ');
  });

  constructor() {
    effect(() => {
      const display = this._display();

      if (!this._isBrowser) return;

      const native = this._native().nativeElement;

      if (native.value !== display) native.value = display;
    });

    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      for (const problem of this._resolvedCountries().problems) {
        console.warn(`[mud-phone-input] ${problem}`);
      }
    });

    // An unknown ISO is a consumer bug worth surfacing, but must not break
    // rendering — `_country()` already falls back to Moldova.
    effect(() => {
      if (typeof ngDevMode !== 'undefined' && !ngDevMode) return;

      const requested = this.country();
      const resolved = this._country().iso;
      const known = requested?.toUpperCase() === resolved.toUpperCase();

      if (requested && !known) {
        console.warn(
          `[mud-phone-input] country="${requested}" is not among the offered countries. Using "${resolved}".`,
        );
      }
    });

    effect(() => {
      const requested = this.country();
      const resolved = this._country().iso;

      if (requested?.toUpperCase() !== resolved.toUpperCase()) {
        this.country.set(resolved);
      }
    });

    effect(() => {
      const value = this.value();

      if (value === this._selfPublished) return;

      this._selfPublished = value;

      const inferred = findCountryByDialCode(value, untracked(() => this._countryList()));

      if (!inferred || inferred.iso === untracked(() => this._country().iso)) return;

      this._skipRebuildFor = inferred.iso;
      this.country.set(inferred.iso);
    });

    effect(() => {
      const iso = this.country();
      const previous = this._previousIso;

      this._previousIso = iso;

      if (previous === undefined || previous === iso) return;

      if (this._skipRebuildFor === iso) {
        this._skipRebuildFor = null;

        return;
      }

      untracked(() => {
        const from = findCountry(previous);
        const national = from ? nationalOf(this.value(), from) : digitsOf(this.value());

        if (!national) return;

        this._publish(national);
      });
    });
  }

  writeValue(value: string | null | undefined): void {
    this.value.set(value ?? '');
  }

  registerOnChange(fn: (value: string) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  /** @description Focuses the national-segment input (also used by signal forms). */
  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  private _publish(nationalDigits: string): void {
    const next = toE164(nationalDigits, this._country());

    this._selfPublished = next;
    this.value.set(next);
    this._onChange(next);
  }

  protected _onInput(event: Event): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    const native = event.target as HTMLInputElement;
    const raw = native.value;
    const caret = native.selectionStart ?? raw.length;
    const digitIndex = digitsBefore(raw, caret);
    const masked = applyMask(raw, this._country());

    this._publish(digitsOf(masked));

    native.value = masked;

    if (this._isBrowser) {
      const next = caretForDigitIndex(masked, digitIndex);

      native.setSelectionRange(next, next);
    }
  }

  protected _onBlur(): void {
    this._focused.set(false);
    this._onTouched();
    this.touch.emit();

    const national = nationalOf(this.value(), this._country());

    this.changed.emit({
      value: this.value(),
      country: this._country().iso,
      complete: isComplete(national, this._country()),
    });
  }

  protected _onFocus(): void {
    this._focused.set(true);
  }

  protected _onClear(): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    this._publish('');
    this._native().nativeElement.value = '';
    this.focus();
  }

  protected _toggleList(): void {
    if (this._effectiveDisabled() || this.readonly()) return;

    if (this._open()) this._closeList();
    else this._openList();
  }

  private _openList(): void {
    if (this._effectiveDisabled() || this.readonly() || this._open()) return;

    // Every open starts from a clean search, priming the current country.
    this._query.set('');
    this._highlighted.set(
      this._filtered().findIndex((country) => country.iso === this._country().iso),
    );
    this._open.set(true);
    this._attachPanel();

    this._highlight(this._highlighted());

    if (this._isBrowser) this._searchEl()?.nativeElement.focus();
  }

  private _closeList(options?: { restoreFocus?: boolean }): void {
    if (!this._open()) return;

    this._open.set(false);
    this._query.set('');
    this._highlighted.set(-1);
    this._detachPanel();

    if (this._isBrowser && options?.restoreFocus !== false) {
      this._trigger()?.nativeElement.focus();
    }
  }

  protected _onTriggerKeydown(event: KeyboardEvent): void {
    if (event.key === 'ArrowDown' || event.key === 'ArrowUp' || event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      this._openList();
    }
  }

  private _highlight(index: number): void {
    this._highlighted.set(index);

    if (!this._isBrowser || index < 0) return;

    const panel = this._overlayRef?.overlayElement;
    const option = panel?.querySelector<HTMLElement>(`[data-option-index="${index}"]`);

    option?.scrollIntoView?.({ block: 'nearest' });
  }

  protected _onSearchInput(event: Event): void {
    this._query.set((event.target as HTMLInputElement).value);

    this._highlighted.set(-1);
  }

  protected _onListKeydown(event: KeyboardEvent): void {
    const count = this._filtered().length;

    switch (event.key) {
      case 'ArrowDown':
        event.preventDefault();

        if (count > 0) this._highlight(Math.min(this._highlighted() + 1, count - 1));

        return;
      case 'ArrowUp':
        event.preventDefault();

        if (count > 0) this._highlight(Math.max(this._highlighted() - 1, 0));

        return;
      case 'Home':
        event.preventDefault();

        if (count > 0) this._highlight(0);

        return;
      case 'End':
        event.preventDefault();

        if (count > 0) this._highlight(count - 1);

        return;
      case 'Enter': {
        event.preventDefault();
        const active = this._filtered()[this._highlighted()];

        if (active) this._selectCountry(active);

        return;
      }
      case 'Escape':
        event.preventDefault();
        this._closeList();

        return;
      case 'Tab':
        // Let focus leave naturally, but do not leave an orphaned panel behind.
        this._closeList({ restoreFocus: false });
    }
  }

  protected _selectCountry(country: MudPhoneCountry): void {
    // Setting the model runs the reconciliation effect, which keeps the digits
    // and swaps the dial code.
    this.country.set(country.iso);
    this._closeList();
  }

  protected _onOptionEnter(index: number): void {
    this._highlighted.set(index);
  }

  private _attachPanel(): void {
    const template = this._panelTemplate();

    if (!this._isBrowser || !template || this._overlayRef?.hasAttached()) return;

    const control = this._control().nativeElement;
    const positionStrategy = this._overlay
      .position()
      .flexibleConnectedTo(control)
      .withFlexibleDimensions(false)
      .withViewportMargin(8)
      .withPush(false)
      .withPositions([
        { originX: 'start', originY: 'bottom', overlayX: 'start', overlayY: 'top', offsetY: 4 },
        { originX: 'start', originY: 'top', overlayX: 'start', overlayY: 'bottom', offsetY: -4 },
      ]);

    this._overlayRef = this._overlay.create({
      positionStrategy,
      scrollStrategy: this._overlay.scrollStrategies.reposition(),
      width: control.getBoundingClientRect().width,
    });

    this._overlayRef.attach(new TemplatePortal(template, this._viewContainerRef));

    this._overlayRef.outsidePointerEvents().subscribe((event) => {
      const target = event.target as Node | null;

      if (target && !control.contains(target)) this._closeList({ restoreFocus: false });
    });
  }

  private _detachPanel(): void {
    this._overlayRef?.dispose();
    this._overlayRef = null;
  }
}

import { NgTemplateOutlet } from '@angular/common';
import type { ElementRef, QueryList } from '@angular/core';
import {
  afterNextRender,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  DestroyRef,
  ViewChildren,
  inject,
  input,
  output,
  signal,
  viewChild,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { CdkStepper } from '@angular/cdk/stepper';
import type { Observable, Subscription } from 'rxjs';
import { merge } from 'rxjs';
import { startWith } from 'rxjs/operators';
import type { MudStep } from './mud-step.component';
import type { MudStepState } from './mud-step-header.component';
import { MUD_STEP_STATES, MudStepHeader } from './mud-step-header.component';

/** Container width below which a horizontal tracker auto-switches to the compact dot rail. */
const AUTO_COMPACT_MAX_WIDTH = 600;

/** Cancelable payload of {@link MudProgressTracker.stepClick}. */
export interface MudProgressTrackerStepClick {
  index: number;
  step: MudStep;
  readonly defaultPrevented: boolean;
  preventDefault(): void;
}

/**
 * ```html
 * <mud-progress-tracker [linear]="true">
 *   <mud-step label="Identity" [stepControl]="identityForm">…</mud-step>
 *   <mud-step label="Review">…</mud-step>
 * </mud-progress-tracker>
 * ```
 */
@Component({
  selector: 'mud-progress-tracker',
  imports: [NgTemplateOutlet, MudStepHeader],
  providers: [{ provide: CdkStepper, useExisting: MudProgressTracker }],
  template: `
    <div
      #track
      class="progress-tracker"
      [class.progress-tracker--vertical]="orientation === 'vertical'"
      [class.progress-tracker--compact]="_isCompact()"
      role="list"
    >
      @for (step of _stepList(); track step; let i = $index) {
        <div class="progress-step" [class]="'progress-step--' + _stateOf(step)" role="listitem">
          <!--
            A real element (not a ::before) so axe can compute the text's
            effective background: ancestor pseudo-elements with a painted
            background make the color-contrast check abstain.
          -->
          <span class="progress-step__connector" aria-hidden="true"></span>
          <mud-step-header
            [id]="_getStepLabelId(i)"
            [state]="_stateOf(step)"
            [index]="i"
            [label]="step.label"
            [secondaryText]="_supportingTextOf(step)"
            [tabIndex]="_getFocusIndex() === i ? 0 : -1"
            [attr.aria-current]="selectedIndex === i ? 'step' : null"
            [attr.aria-controls]="_getStepContentId(i)"
            [attr.aria-disabled]="step.isNavigable() ? null : true"
            [attr.aria-label]="step.ariaLabel || null"
            [attr.aria-labelledby]="!step.ariaLabel && step.ariaLabelledby ? step.ariaLabelledby : null"
            (click)="_onHeaderClick(step)"
            (keydown)="_onKeydown($event)"
          />
          @if (orientation === 'vertical') {
            <div
              class="progress-step__panel"
              role="region"
              [id]="_getStepContentId(i)"
              [attr.aria-labelledby]="_getStepLabelId(i)"
              [hidden]="selectedIndex !== i"
            >
              <ng-container [ngTemplateOutlet]="step.content" />
            </div>
          }
        </div>
      }
    </div>
    @if (orientation === 'horizontal') {
      <div class="progress-tracker__content">
        @for (step of _stepList(); track step; let i = $index) {
          <div
            class="progress-tracker__panel"
            role="region"
            [id]="_getStepContentId(i)"
            [attr.aria-labelledby]="_getStepLabelId(i)"
            [hidden]="selectedIndex !== i"
          >
            <ng-container [ngTemplateOutlet]="step.content" />
          </div>
        }
      </div>
    }
  `,
  host: {
    class: 'progress-tracker-container',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudProgressTracker extends CdkStepper {
  /**
   * CdkStepper declares `_stepHeader` as a CONTENT query, but our headers
   * live in this component's view — override with a view query (same
   * pattern as MatStepper) so FocusKeyManager finds them.
   */
  @ViewChildren(MudStepHeader) declare _stepHeader: QueryList<MudStepHeader>;

  /**
   * @description Forces the number-less dot rail (labels visually hidden but still
   * announced). Horizontal trackers also switch to it automatically when
   * their container is narrower than 600px, matching the official tracker.
   */
  readonly compact = input(false, { transform: booleanAttribute });

  /**
   * Emitted before a click on an actionable header selects the step. Call
   * `preventDefault()` on the event to keep the selection unchanged
   * (official mudStepClick contract).
   */
  readonly stepClick = output<MudProgressTrackerStepClick>();

  protected readonly _stepList = signal<readonly MudStep[]>([]);

  private readonly _autoCompact = signal(false);
  protected readonly _isCompact = computed(
    () => this.compact() || (this.orientation === 'horizontal' && this._autoCompact()),
  );

  private readonly _track = viewChild.required<ElementRef<HTMLElement>>('track');

  /** Bumped on reactive-forms statusChanges so _stateOf re-evaluates. */
  private readonly _controlStatus = signal(0);
  private readonly _destroyRef = inject(DestroyRef);
  private _statusSub: Subscription | null = null;

  constructor() {
    super();

    afterNextRender(() => {
      if (typeof ResizeObserver === 'undefined') return;

      const observer = new ResizeObserver((entries) => {
        const width = entries[0]?.contentRect.width ?? Number.POSITIVE_INFINITY;

        this._autoCompact.set(width < AUTO_COMPACT_MAX_WIDTH);
      });

      observer.observe(this._track().nativeElement);
      this._destroyRef.onDestroy(() => observer.disconnect());
    });
  }

  override ngAfterContentInit(): void {
    super.ngAfterContentInit();

    this.steps.changes
      .pipe(startWith(null), takeUntilDestroyed(this._destroyRef))
      .subscribe(() => {
        const steps = this.steps.toArray() as MudStep[];

        this._stepList.set(steps);
        this._watchControls(steps);
      });
    this._destroyRef.onDestroy(() => this._statusSub?.unsubscribe());
  }

  /**
   * @docs-private Derives the visual state of a step (spec state model).
   * */
  protected _stateOf(step: MudStep): MudStepState {
    this._controlStatus();

    const forced = step.state as MudStepState | undefined;

    if (forced && (MUD_STEP_STATES as readonly string[]).includes(forced)) {
      return forced;
    }

    if (step.isSelected()) {
      return 'current';
    }

    if (step.hasError) {
      return 'blocked';
    }

    if (step.completed) {
      return 'completed';
    }

    return step.isNavigable() ? 'available' : 'incomplete';
  }

  /** @docs-private errorMessage replaces the supporting text while blocked. */
  protected _supportingTextOf(step: MudStep): string | undefined {
    if (this._stateOf(step) === 'blocked' && step.errorMessage) {
      return step.errorMessage;
    }

    return step.supportingText();
  }

  /** @docs-private */
  protected _onHeaderClick(step: MudStep): void {
    if (!step.isNavigable()) return;

    let prevented = false;
    const event: MudProgressTrackerStepClick = {
      index: this._stepList().indexOf(step),
      step,
      get defaultPrevented() {
        return prevented;
      },
      preventDefault() {
        prevented = true;
      },
    };

    this.stepClick.emit(event);

    if (!prevented) step.select();
  }

  /**
   * Signal-forms fields are functions and already reactive; only
   * reactive-forms controls (objects with statusChanges) need their
   * validity bridged into the signal graph for OnPush/zoneless updates.
   */
  private _watchControls(steps: readonly MudStep[]): void {
    this._statusSub?.unsubscribe();
    this._statusSub = null;

    const observables = steps
      .map((step) => step.stepControl as { statusChanges?: Observable<unknown> } | undefined)
      .filter(
        (control): control is { statusChanges: Observable<unknown> } =>
          !!control && typeof control !== 'function' && !!control.statusChanges,
      )
      .map((control) => control.statusChanges);

    if (observables.length) {
      this._statusSub = merge(...observables).subscribe(() =>
        this._controlStatus.update((v) => v + 1),
      );
    }
  }
}

import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  contentChildren,
  inject,
  input,
  viewChild,
} from '@angular/core';
import type { ElementRef } from '@angular/core';
import { MudLabel } from 'ngx-mud-ui/label';
import { MudInlineMessage } from 'ngx-mud-ui/inline-message';
import { MudRadioGroup } from './mud-radio-group.component';

let nextUniqueId = 0;

/**
 * One option inside a {@link MudRadioGroup}. Its checked state DERIVES from
 * the group's value (single source of truth); a radio cannot be used outside
 * a group — for a single yes/no toggle use `mud-checkbox`.
 *
 * ```html
 * <mud-radio value="mpay">
 *   <mud-label>MPay</mud-label>
 *   <mud-inline-message hideIcon>Fără comision.</mud-inline-message>
 * </mud-radio>
 * ```
 */
@Component({
  selector: 'mud-radio',
  templateUrl: './mud-radio.component.html',
  host: {
    '[class]': '_hostClasses()',
  },
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudRadio<T = unknown> {
  private readonly _group = inject<MudRadioGroup<T>>(MudRadioGroup);

  /** @description The value this option contributes to the group (compared with Object.is). */
  readonly value = input.required<T>();

  /** @description Disables this option on top of the group-level disabled. */
  readonly disabled = input(false, { transform: booleanAttribute });

  /** @description Accessible name when no visible label is rendered. */
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });

  private readonly _native = viewChild.required<ElementRef<HTMLInputElement>>('native');

  /** @docs-private Focuses this option's native input (used by the group). */
  _focus(options?: FocusOptions): void {
    this._native().nativeElement.focus(options);
  }

  /** @docs-private Projected label element (ngx-mud-ui/label). */
  protected readonly _label = contentChild(MudLabel);

  /** @docs-private Consumer-projected assistive messages. */
  private readonly _messages = contentChildren(MudInlineMessage);

  protected readonly _hasLabel = computed(() => !!this._label());

  protected readonly _hasMessages = computed(() => this._messages().length > 0);

  protected readonly _id = `mud-radio-${nextUniqueId++}`;
  protected readonly _assistiveId = `${this._id}-assistive`;

  protected readonly _checked = computed(() => Object.is(this._group.value(), this.value()));

  protected readonly _effectiveDisabled = computed(
    () => this.disabled() || this._group._effectiveDisabled(),
  );

  protected readonly _name = computed(() => this._group._name());
  protected readonly _required = computed(() => this._group.required());
  protected readonly _readonly = computed(() => this._group.readonly());
  protected readonly _invalid = computed(() => this._group._effectiveInvalid());

  protected readonly _describedBy = computed<string | null>(() =>
    this._hasMessages() ? this._assistiveId : null,
  );

  protected readonly _ariaLabel = computed<string | null>(() => {
    if (this._hasLabel()) return null;

    return this.ariaLabel() ?? null;
  });

  protected readonly _hostClasses = computed(() => {
    const classes = ['selection-control', 'selection-control--radio'];

    if (this._group.size() === 'small') classes.push('selection-control--sm');

    if (this._checked()) classes.push('is-checked');

    if (this._effectiveDisabled()) classes.push('is-disabled');

    if (this._readonly()) classes.push('is-readonly');

    if (this._invalid()) classes.push('is-invalid');

    return classes.join(' ');
  });

  protected _onClick(event: MouseEvent): void {
    if (this._readonly()) event.preventDefault();
  }

  protected _onKeydown(event: KeyboardEvent): void {
    // click-blocking covers pointer and Space, but arrow keys select
    // natively without a click — stop them before the browser acts.
    if (!this._readonly()) return;

    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight'].includes(event.key)) {
      event.preventDefault();
    }
  }

  protected _onNativeChange(event: Event): void {
    if ((event.target as HTMLInputElement).checked) this._group._select(this.value());
  }
}

