  // ----- ControlValueAccessor (reactive/template-driven forms) -----

  writeValue(value: boolean | null | undefined): void {
    this.checked.set(!!value);
  }

  registerOnChange(fn: (checked: boolean) => void): void {
    this._onChange = fn;
  }

  registerOnTouched(fn: () => void): void {
    this._onTouched = fn;
  }

  setDisabledState(isDisabled: boolean): void {
    this._cvaDisabled.set(isDisabled);
  }

  // ----- FormCheckboxControl extras -----

  /** Focuses the native control (also used by signal forms' focus requests). */
  focus(options?: FocusOptions): void {
    if (!this._isBrowser) return;

    this._native().nativeElement.focus(options);
  }

  // ----- internal handlers -----

  protected _onNativeChange(event: Event): void {
    const next = (event.target as HTMLInputElement).checked;

    this.checked.set(next);
    this._onChange(next);
  }

  protected _onBlur(): void {
    this._onTouched();
    this.touch.emit();
  }
}

import {
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  computed,
  contentChild,
  input,
  numberAttribute,
  signal,
  TemplateRef,
  viewChild,
} from '@angular/core';
import { MudTabLabel } from './mud-tab-label.directive';

let uniqueId = 0;

/**
 * ```html
 * <mud-tab label="Overview">…content…</mud-tab>
 * ```
 */
@Component({
  selector: 'mud-tab',
  template: `<ng-template><ng-content /></ng-template>`,
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudTab {
  readonly label = input('');
  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });
  readonly ariaLabelledby = input<string | undefined>(undefined, { alias: 'aria-labelledby' });
  readonly disabled = input(false, { transform: booleanAttribute });
  readonly id = input<string | undefined>(undefined);
  /**
   * @description Count pill rendered after the label (official tabs badge).
   * Shown when >= 0; null hides it.
   */
  readonly badgeCount = input<number | null, number | string | null | undefined>(null, {
    transform: (value) => (value == null || value === '' ? null : numberAttribute(value)),
  });

  readonly content = viewChild.required(TemplateRef);
  readonly templateLabel = contentChild(MudTabLabel);

  /** @docs-private Written by MudTabGroup only. */
  readonly _isActive = signal(false);
  /** @docs-private Written by MudTabGroup only. */
  readonly _position = signal(0);

  /** Whether this tab is the group's selected tab. */
  readonly isActive = this._isActive.asReadonly();

  /** This tab's index within the group. */
  readonly position = this._position.asReadonly();

  private readonly _uid = `mud-tab-${uniqueId++}`;

  readonly tabId = computed(() => this.id() ?? this._uid);
}

import {
  afterNextRender,
  booleanAttribute,
  ChangeDetectionStrategy,
  Component,
  contentChildren,
  DestroyRef,
  effect,
  inject,
  input,
  model,
  output,
  PLATFORM_ID,
  signal,
  viewChild,
  viewChildren,
} from '@angular/core';
import type { ElementRef } from '@angular/core';
import { isPlatformBrowser, NgTemplateOutlet } from '@angular/common';
import { CdkPortalOutlet } from '@angular/cdk/portal';
import { MudTab } from './mud-tab.component';
import type { MudTabChangeEvent } from './mud-tab-change-event';

/**
 * ```html
 * <mud-tab-group [(selectedIndex)]="index" (selectedTabChange)="onChange($event)">
 *   <mud-tab label="Overview">…</mud-tab>
 *   <mud-tab label="Details" [disabled]="true">…</mud-tab>
 * </mud-tab-group>
 * ```
 */
@Component({
  selector: 'mud-tab-group',
  imports: [NgTemplateOutlet, CdkPortalOutlet],
  template: `
    <div class="tabs" [class.tabs--stretch]="stretchTabs()" [class.tabs--sm]="size() === 'sm'">
      <div
        class="tab-header"
        [class.tab-header--overflow-start]="canScrollStart()"
        [class.tab-header--overflow-end]="canScrollEnd()"
      >
        @if (canScrollStart()) {
          <button
            type="button"
            class="tab-scroll tab-scroll--prev"
            tabindex="-1"
            aria-hidden="true"
            (click)="scrollByStep(-1)"
          >
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M15 6l-6 6 6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
        }

        <div class="tab-viewport" #viewport (scroll)="updateOverflow()">
          <div
            class="tab-buttons"
            #tabStrip
            role="tablist"
            aria-orientation="horizontal"
            [attr.aria-label]="ariaLabel()"
            [attr.aria-labelledby]="ariaLabelledby()"
          >
            @for (tab of tabs(); track tab; let i = $index) {
              <button
                #tabButton
                type="button"
                role="tab"
                class="tab-button"
                [class.active]="i === selectedIndex()"
                [id]="tab.tabId()"
                [disabled]="tab.disabled()"
                [attr.aria-selected]="i === selectedIndex()"
                [attr.aria-controls]="tab.tabId() + '-panel'"
                [attr.aria-label]="tab.ariaLabel()"
                [attr.aria-labelledby]="tab.ariaLabelledby()"
                [attr.tabindex]="i === selectedIndex() ? 0 : -1"
                (click)="selectTab(i)"
                (focus)="focusedIndex.set(i)"
                (keydown)="onKeydown($event)"
              >
                @if (tab.templateLabel(); as label) {
                  <ng-template [cdkPortalOutlet]="label" />
                } @else {
                  {{ tab.label() }}
                }
                @if (tab.badgeCount() !== null) {
                  <span class="tab-badge">{{ tab.badgeCount() }}</span>
                }
              </button>
            }
          </div>
        </div>

        @if (canScrollEnd()) {
          <button
            type="button"
            class="tab-scroll tab-scroll--next"
            tabindex="-1"
            aria-hidden="true"
            (click)="scrollByStep(1)"
          >
            <svg viewBox="0 0 24 24" fill="none" aria-hidden="true">
              <path d="M9 6l6 6-6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
        }
      </div>

      <div class="tab-panels">
        @for (tab of tabs(); track tab; let i = $index) {
          <div
            role="tabpanel"
            class="tab-panel"
            [class.active]="i === selectedIndex()"
            [id]="tab.tabId() + '-panel'"
            [attr.aria-labelledby]="tab.tabId()"
            [attr.tabindex]="i === selectedIndex() ? contentTabIndex() : null"
            [hidden]="i !== selectedIndex()"
          >
            <ng-container [ngTemplateOutlet]="tab.content()" />
          </div>
        }
      </div>
    </div>
  `,
  styleUrl: './mud-tab-group.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class MudTabGroup {
  private readonly _destroyRef = inject(DestroyRef);
  private readonly _isBrowser = isPlatformBrowser(inject(PLATFORM_ID));

  readonly tabs = contentChildren(MudTab);

  readonly ariaLabel = input<string | undefined>(undefined, { alias: 'aria-label' });
  readonly ariaLabelledby = input<string | undefined>(undefined, { alias: 'aria-labelledby' });
  readonly contentTabIndex = input<number | null>(null);
  readonly stretchTabs = input(false, { transform: booleanAttribute });
  readonly size = input<'md' | 'sm'>('md');
  readonly selectedIndex = model(0);

  readonly selectedTabChange = output<MudTabChangeEvent>();

  protected readonly focusedIndex = signal(0);
  protected readonly canScrollStart = signal(false);
  protected readonly canScrollEnd = signal(false);

  private readonly _buttons = viewChildren<ElementRef<HTMLButtonElement>>('tabButton');
  private readonly _viewport = viewChild<ElementRef<HTMLElement>>('viewport');
  private readonly _strip = viewChild<ElementRef<HTMLElement>>('tabStrip');

  private _lastEmitted = -1;
  private _initialized = false;

  constructor() {
    afterNextRender(() => {
      this.updateOverflow();

      if (typeof ResizeObserver === 'undefined') {
        return;
      }

      const observer = new ResizeObserver(() => this.updateOverflow());
      const viewport = this._viewport()?.nativeElement;
      const strip = this._strip()?.nativeElement;

      if (viewport) {
        observer.observe(viewport);
      }

      if (strip) {
        observer.observe(strip);
      }

      this._destroyRef.onDestroy(() => observer.disconnect());
    });

    effect(() => {
      const tabs = this.tabs();
      const index = this.selectedIndex();

      /**
       * The selected tab can disappear (an @if/@for removes it) or become
       * disabled (programmatic selectedIndex writes bypass the interactive
       * guard; a selected tab's [disabled] can flip). Either way the
       * selection must land on an enabled tab, otherwise no panel is shown —
       * or a disabled tab is presented as active — and every tab button
       * keeps tabindex="-1", making the tablist unreachable by keyboard.
       * */
      if (tabs.length > 0 && (!tabs[index] || tabs[index].disabled())) {
        const fallback = this._closestEnabled(tabs[index] ? index : tabs.length - 1);

        if (fallback >= 0 && fallback !== index) {
          this.selectedIndex.set(fallback);

          return;
        }
      }

      tabs.forEach((tab, i) => {
        tab._position.set(i);
        tab._isActive.set(i === index);
      });

      const tab = tabs[index];

      if (tab) {
        if (this._initialized && index !== this._lastEmitted) {
          this.selectedTabChange.emit({ index, tab });
        }

        this._lastEmitted = index;
        this._initialized = true;
      }
    });
  }

  selectTab(index: number): void {
    const tabs = this.tabs();

    if (index < 0 || index >= tabs.length || tabs[index].disabled()) {
      return;
    }

    this.selectedIndex.set(index);
    this.focusedIndex.set(index);
  }

  focusTab(index: number): void {
    if (!this._isBrowser) return;

    if (index >= 0 && index < this.tabs().length) {
      this.focusedIndex.set(index);

      const button = this._buttons()[index]?.nativeElement;

      button?.focus();
      button?.scrollIntoView?.({ block: 'nearest', inline: 'nearest' });
    }
  }

  protected updateOverflow(): void {
    const viewport = this._viewport()?.nativeElement;

    if (!viewport) {
      this.canScrollStart.set(false);
      this.canScrollEnd.set(false);

      return;
    }

    const maxScroll = viewport.scrollWidth - viewport.clientWidth;
    const left = viewport.scrollLeft;

    this.canScrollStart.set(left > 1);
    this.canScrollEnd.set(maxScroll > 1 && left < maxScroll - 1);
  }

  protected scrollByStep(direction: 1 | -1): void {
    const viewport = this._viewport()?.nativeElement;

    viewport?.scrollBy({ left: direction * viewport.clientWidth * 0.75, behavior: 'smooth' });
  }

  protected onKeydown(event: KeyboardEvent): void {
    const count = this.tabs().length;

    if (count === 0) {
      return;
    }

    // Automatic activation (official): arrows move focus AND selection.
    switch (event.key) {
      case 'ArrowRight':
      case 'ArrowDown':
        this._activate(this._nextEnabled(this.focusedIndex(), 1));
        break;
      case 'ArrowLeft':
      case 'ArrowUp':
        this._activate(this._nextEnabled(this.focusedIndex(), -1));
        break;
      case 'Home':
        this._activate(this._nextEnabled(-1, 1));
        break;
      case 'End':
        this._activate(this._nextEnabled(count, -1));
        break;
      case 'Enter':
      case ' ':
        this.selectTab(this.focusedIndex());
        break;
      default:
        return;
    }

    event.preventDefault();
  }

  private _activate(index: number): void {
    this.selectTab(index);
    this.focusTab(index);
  }

  private _closestEnabled(from: number): number {
    const tabs = this.tabs();

    for (let i = Math.min(from, tabs.length - 1); i >= 0; i--) {
      if (!tabs[i].disabled()) return i;
    }

    for (let i = from + 1; i < tabs.length; i++) {
      if (!tabs[i].disabled()) return i;
    }

    return -1;
  }

  private _nextEnabled(from: number, direction: 1 | -1): number {
    const tabs = this.tabs();
    const count = tabs.length;
    let index = from;

    for (let step = 0; step < count; step++) {
      index = (index + direction + count) % count;

      if (!tabs[index].disabled()) {
        return index;
      }
    }

    return Math.max(0, Math.min(from, count - 1));
  }
}

