:host {
  display: block;
}

.tab-header {
  display: flex;
  align-items: stretch;
  border-bottom: 1px solid var(--color-border-base-default, #d9d9d9);
}

.tab-viewport {
  flex: 1 1 auto;
  min-width: 0;
  overflow-x: auto;
  scrollbar-width: none; // Firefox
  -ms-overflow-style: none; // legacy Edge
  --fade-start: 0px;
  --fade-end: 0px;
  -webkit-mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--fade-start),
    #000 calc(100% - var(--fade-end)),
    transparent 100%
  );
  mask-image: linear-gradient(
    to right,
    transparent 0,
    #000 var(--fade-start),
    #000 calc(100% - var(--fade-end)),
    transparent 100%
  );
}

.tab-viewport::-webkit-scrollbar {
  display: none; // WebKit
}

.tab-header--overflow-start .tab-viewport {
  --fade-start: 48px;
}

.tab-header--overflow-end .tab-viewport {
  --fade-end: 48px;
}

.tabs--sm .tab-header--overflow-start .tab-viewport {
  --fade-start: 32px;
}

.tabs--sm .tab-header--overflow-end .tab-viewport {
  --fade-end: 32px;
}

.tab-buttons {
  display: flex;
  gap: 8px;
  width: fit-content;
}

.tabs--stretch .tab-viewport {
  overflow-x: visible;
  mask-image: none;
  -webkit-mask-image: none;
}

.tabs--stretch .tab-buttons {
  width: 100%;
}

.tabs--stretch .tab-button {
  flex: 1;
  justify-content: center;
}

.tab-scroll {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: center;
  align-self: stretch;
  width: 32px;
  padding: 12px 4px;
  background: var(--color-background-base-default, #fff);
  border: none;
  color: var(--color-icon-base-secondary, #383838);
  cursor: pointer;
  transition: color 150ms ease-out;
}

.tab-scroll svg {
  width: 24px;
  height: 24px;
}

.tabs--sm .tab-scroll {
  padding: 8px 4px;
}

.tabs--sm .tab-scroll svg {
  width: 20px;
  height: 20px;
}

.tab-scroll:hover {
  color: var(--color-icon-base-default, #121212);
}

.tab-button {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  height: 48px;
  min-width: 40px;
  padding: 0 16px;
  background: transparent;
  border: none;
  border-bottom: 2px solid transparent;
  color: var(--color-text-base-secondary, #383838);
  font-family: var(--font-family-primary, 'Onest', system-ui, sans-serif);
  font-size: 16px;
  font-weight: 400;
  line-height: 24px;
  cursor: pointer;
  transition:
    color 150ms ease-out,
    border-color 150ms ease-out;

  mud-icon svg,
  > svg {
    width: 20px;
    height: 20px;
    flex-shrink: 0;
  }

  &:hover:not(.active):not(:disabled) {
    color: var(--color-text-base-default, #121212);
  }

  &.active {
    color: var(--color-text-brand-default, #0058d2);
    border-color: var(--color-border-brand-default, #0058d2);
    font-weight: 500;
  }

  &:focus-visible {
    outline: none;
    box-shadow:
      inset 0 0 0 var(--focus-ring-inner-width, 2px) var(--focus-ring-inner-color, #fff),
      inset 0 0 0 calc(var(--focus-ring-inner-width, 2px) + var(--focus-ring-outer-width, 3px))
        var(--focus-ring-outer-color, var(--blue-sky-500, #3379db));
  }

  &:disabled {
    color: var(--color-text-disabled-default, #B2B2B2);
    cursor: not-allowed;
  }
}

// The official count pill after the label.
.tab-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 24px;
  min-height: 24px;
  padding: 0 8px;
  border-radius: var(--border-radius-full, 9999px);
  background: var(--color-background-base-tertiary, #f1f1f1);
  color: var(--color-text-base-default, #121212);
  font-size: 14px;
  line-height: 20px;
  font-weight: 500;
}

.tab-button:disabled .tab-badge {
  color: var(--color-text-disabled-default, #B2B2B2);
}

// Explicit compact variant (size="sm").
.tabs--sm .tab-button {
  height: 40px;
  padding: 0 12px;
  font-size: 14px;
  line-height: 20px;
}

.tabs--sm .tab-badge {
  min-width: 20px;
  min-height: 20px;
  padding: 0 4px;
  font-size: 12px;
  line-height: 16px;
}

.tab-panels {
  margin-top: 16px;
}

.tab-panel {
  display: none;

  &.active {
    display: block;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tab-button,
  .tab-scroll {
    transition: none;
  }
}

