@use 'sass:math';

:host {
  position: relative;
  display: block;
  // The padding creates the visual gap to the trigger and hosts the arrow.
  padding: var(--spacing-8, 8px);
  opacity: 0;
  transform: scale(0.95);
  transition:
    opacity 150ms ease-out,
    transform 150ms ease-out;
}

:host(.show) {
  opacity: 1;
  transform: scale(1);
}

@media (prefers-reduced-motion: reduce) {
  :host {
    transition: none;
    transform: none;
  }
}

.tooltip-inner {
  background: var(--color-background-base-inverse-default, #1e1e1e);
  color: var(--color-text-base-inverse-default, #ffffff);
  border-radius: var(--border-radius-4, 4px);
  max-width: var(--mud-tooltip-max-width, 280px);
  font-size: 14px;
  line-height: 20px;
  font-weight: 400;
  box-shadow: 0 4px 10px rgb(0 0 0 / 15%);
}

:host(.tooltip--small) .tooltip-inner {
  padding: var(--spacing-8, 8px) var(--spacing-12, 12px);
}

:host(.tooltip--large) .tooltip-inner {
  border-radius: var(--border-radius-6, 6px);
  padding: var(--spacing-12, 12px) var(--spacing-16, 16px);
}

.tooltip-title {
  font-weight: 500;
  margin-bottom: var(--spacing-2, 2px);
}

// Coach hint line (official: 12/16 at 0.72 opacity, 6px above).
.tooltip-hint {
  margin-top: var(--spacing-6, 6px);
  font-size: 12px;
  line-height: 16px;
  opacity: 0.72;
}

:host(.tooltip--with-close) .tooltip-inner {
  padding-right: var(--spacing-48, 48px);
}

.tooltip-close {
  position: absolute;
  top: var(--spacing-12, 12px);
  right: var(--spacing-8, 8px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  // ≥32px pointer/touch target; the visible icon stays 16px.
  width: 32px;
  height: 32px;
  padding: 0;
  border: none;
  border-radius: var(--border-radius-6, 6px);
  background: transparent;
  color: var(--color-text-base-inverse-default, #ffffff);
  cursor: pointer;
  opacity: 0.7;
  transition:
    opacity 150ms ease-out,
    background-color 150ms ease-out;

  &:hover {
    opacity: 1;
    background: var(--color-background-base-inverse-default-hover, #383838);
  }

  &:focus-visible {
    opacity: 1;
    outline: 2px solid var(--color-text-base-inverse-default, #ffffff);
    outline-offset: 1px;
  }

  svg {
    width: 16px;
    height: 16px;
  }
}

// The arrow is a rotated square whose diagonal is the official triangle
// width (16px small / 24px large -> 8px / 12px visible height). Its tip
// pokes (s·√2 − s)/2 past its own box; inset by that plus 2px so the tip
// always sits exactly 2px away from the trigger, whichever side it's on.
$arrow-size: 11.31px; // 16px / sqrt(2)
$arrow-size-lg: 16.97px; // 24px / sqrt(2)
$arrow-inset: 2px + math.div($arrow-size * (math.sqrt(2) - 1), 2);

.tooltip-arrow {
  position: absolute;
  width: $arrow-size;
  height: $arrow-size;
  background: var(--color-background-base-inverse-default, #1e1e1e);
  transform: rotate(45deg);
}

:host(.tooltip--large) .tooltip-arrow {
  width: $arrow-size-lg;
  height: $arrow-size-lg;
}

:host(.tooltip--top-left) .tooltip-arrow {
  bottom: $arrow-inset;
  left: 12px;
  border-radius: 0 0 3px 0;
}

:host(.tooltip--top-center) .tooltip-arrow {
  bottom: $arrow-inset;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 0 0 3px 0;
}

:host(.tooltip--top-right) .tooltip-arrow {
  bottom: $arrow-inset;
  right: 12px;
  border-radius: 0 0 3px 0;
}

:host(.tooltip--bottom-left) .tooltip-arrow {
  top: $arrow-inset;
  left: 12px;
  border-radius: 3px 0 0 0;
}

:host(.tooltip--bottom-center) .tooltip-arrow {
  top: $arrow-inset;
  left: 50%;
  transform: translateX(-50%) rotate(45deg);
  border-radius: 3px 0 0 0;
}

:host(.tooltip--bottom-right) .tooltip-arrow {
  top: $arrow-inset;
  right: 12px;
  border-radius: 3px 0 0 0;
}

:host(.tooltip--left-top) .tooltip-arrow {
  right: $arrow-inset;
  top: 12px;
  border-radius: 0 3px 0 0;
}

:host(.tooltip--left-center) .tooltip-arrow {
  right: $arrow-inset;
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
  border-radius: 0 3px 0 0;
}

:host(.tooltip--left-bottom) .tooltip-arrow {
  right: $arrow-inset;
  bottom: 12px;
  border-radius: 0 3px 0 0;
}

:host(.tooltip--right-top) .tooltip-arrow {
  left: $arrow-inset;
  top: 12px;
  border-radius: 0 0 0 3px;
}

:host(.tooltip--right-center) .tooltip-arrow {
  left: $arrow-inset;
  top: 50%;
  transform: translateY(-50%) rotate(45deg);
  border-radius: 0 0 0 3px;
}

:host(.tooltip--right-bottom) .tooltip-arrow {
  left: $arrow-inset;
  bottom: 12px;
  border-radius: 0 0 0 3px;
}

